#####Creating DAGS for all models####

#MET Validity DAG
Vardag <- dagitty('dag {
 Conc [pos="-0.6,-0.4"]
 Variable [pos="-0.1,-0.4"]
 Sex [pos="-0.35,-0.45"]
 "Stage/Task" [pos="-0.1,-0.35"]
   Conc -> Variable
   Conc -> Sex
   Sex -> Variable
   "Stage/Task" -> Variable
   }
'
)
drawdag(Vardag)

Vardag_plot <- ggdag(Vardag,text_size = 2.3) +theme_dag()
Vardag_plot

#MET Prognosis DAG
Prognosisdag <- dagitty('dag {
 MET [pos="-0.6,-0.4"]
 RL [pos="-0.1,-0.4"]
   MET -> RL
   }
'
)
drawdag(Prognosisdag)
PrognosisDag_plot <- ggdag(Prognosisdag,text_size = 2.3) +theme_dag()
PrognosisDag_plot

#Creating a figure that contains all the DAGs for this manuscript
dag_new <- plot_grid(Vardag_plot,PrognosisDag_plot,labels = "AUTO",ncol=2)
dag_new

#######Bayesian Analyses#######
#####Heart Rate Analyses#####
  #####Loading in HR models#####
met_hr_prior_mod <- stan_model("met_hr_prior.stan")
met_hr_mod <- stan_model("met_hr.stan")
met_maxhr_prior_mod <- stan_model("met_maxhr_prior.stan")
met_maxhr_mod <- stan_model("met_maxhr.stan")

  ######Heart Rate Data Set Up######
colnames(bl_conc6tp_data)
hr_analyses_all <- bl_conc6tp_data[c(1,4,22,479,480,464,465,467,468,470,471,473,474)]
colnames(hr_analyses_all)
hr_analyses_all[,c(4:13)] <- lapply(4:ncol(hr_analyses_all), function(x) as.numeric(hr_analyses_all[[x]]))
colnames(hr_analyses_all)

#Going to delete the participants that don't have any HR
hr_analyses_all <- hr_analyses_all[!(is.na(hr_analyses_all$rest_hr) & 
     is.na(hr_analyses_all$rest_maxhr) & is.na(hr_analyses_all$met1_hr) &
    is.na(hr_analyses_all$met1_maxhr) & is.na(hr_analyses_all$met2_hr) & 
    is.na(hr_analyses_all$met2_maxhr) & is.na(hr_analyses_all$met3_hr) &
    is.na(hr_analyses_all$met4_hr) & is.na(hr_analyses_all$met4_maxhr)),]
#Creating an ID for the columns
hr_analyses_all$new_id <- substr(hr_analyses_all$unique_id,start=5,stop=7)
hr_analyses_all$new_id <- sub("^0+", "", hr_analyses_all$new_id)
hr_analyses_all$new_id <- as.numeric(hr_analyses_all$new_id)
hr_analyses_all$new_id <- match(hr_analyses_all$new_id, unique(hr_analyses_all$new_id))
unique(hr_analyses_all$new_id)

#Now creating a group ID
unique(hr_analyses_all$redcap_event_name)
hr_analyses_all$group <- ifelse(hr_analyses_all$redcap_event_name == "Concussion Week 1",2,
    ifelse(hr_analyses_all$redcap_event_name == "Concussion Week 2",2,
    ifelse(hr_analyses_all$redcap_event_name == "Concussion Week 3",2,
    ifelse(hr_analyses_all$redcap_event_name == "Concussion Week 4",2,
    ifelse(hr_analyses_all$redcap_event_name == "Concussion Week 6",2,
    ifelse(hr_analyses_all$redcap_event_name == "Concussion Week 8",2,1))))))

unique(hr_analyses_all$redcap_event_name)
hr_analyses_all$time_point <- ifelse(hr_analyses_all$redcap_event_name == " Healthy",1,
       ifelse(hr_analyses_all$redcap_event_name == "Concussion Week 1",2,
       ifelse(hr_analyses_all$redcap_event_name == "Concussion Week 2",3,
       ifelse(hr_analyses_all$redcap_event_name == "Concussion Week 3",4,
       ifelse(hr_analyses_all$redcap_event_name == "Concussion Week 4",5,
       ifelse(hr_analyses_all$redcap_event_name == "Concussion Week 6",6,7))))))

colnames(hr_analyses_all)
#Mean Ave
mean_hr_df_wide <- gather(hr_analyses_all[c(4,6,8,10,12)], key = 'stage', value = 'mean_hr')
mean_hr_df_wide$new_id <- rep(hr_analyses_all$new_id,5)
mean_hr_df_wide$sex <- rep(hr_analyses_all$Sex,5)
mean_hr_df_wide$group <- rep(hr_analyses_all$group,5)
mean_hr_df_wide$time_point <- rep(hr_analyses_all$time_point,5)
mean_hr_df_wide$stage <- match(mean_hr_df_wide$stage, unique(mean_hr_df_wide$stage))
by(mean_hr_df_wide$mean_hr,mean_hr_df_wide$time_point,summary)

#Now going to delete any NAs in the data frame
length(which(is.na(mean_hr_df_wide$mean_hr)))
mean_hr_df_wide <- mean_hr_df_wide[complete.cases(mean_hr_df_wide) == TRUE, ]
unique(mean_hr_df_wide$stage)
unique(mean_hr_df_wide$sex)
unique(mean_hr_df_wide$group)
unique(mean_hr_df_wide$time_point)

