ppc_hr_stu_t_func <- function(extracted_samples, variable) {
  extracted_samples <- extracted_samples[c(1:17,375:444,18,19,231:233)]
  colnames(extracted_samples) <- c("nu","ctl","conc","male","female","bl","onewpi","twowpi",
    "threewpi","fourwpi","sixwpi","eightwpi","rest","stg1","stg2","stg3","stg4",
    "ctl_f_bl_rest.int","ctl_m_bl_rest.int","ctl_f_bl_stg1.int","ctl_m_bl_stg1.int",
    "ctl_f_bl_stg2.int","ctl_m_bl_stg2.int","ctl_f_bl_stg3.int","ctl_m_bl_stg3.int",
    "ctl_f_bl_stg4.int","ctl_m_bl_stg4.int","conc_f_1wpi_rest.int","conc_m_1wpi_rest.int",
    "conc_f_1wpi_stg1.int","conc_m_1wpi_stg1.int","conc_f_1wpi_stg2.int","conc_m_1wpi_stg2.int",
    "conc_f_1wpi_stg3.int","conc_m_1wpi_stg3.int","conc_f_1wpi_stg4.int","conc_m_1wpi_stg4.int",
    "conc_f_2wpi_rest.int","conc_m_2wpi_rest.int","conc_f_2wpi_stg1.int","conc_m_2wpi_stg1.int",
    "conc_f_2wpi_stg2.int","conc_m_2wpi_stg2.int","conc_f_2wpi_stg3.int","conc_m_2wpi_stg3.int",
    "conc_f_2wpi_stg4.int","conc_m_2wpi_stg4.int","conc_f_3wpi_rest.int","conc_m_3wpi_rest.int",
    "conc_f_3wpi_stg1.int","conc_m_3wpi_stg1.int","conc_f_3wpi_stg2.int","conc_m_3wpi_stg2.int",
    "conc_f_3wpi_stg3.int","conc_m_3wpi_stg3.int","conc_f_3wpi_stg4.int","conc_m_3wpi_stg4.int",
    "conc_f_4wpi_rest.int","conc_m_4wpi_rest.int","conc_f_4wpi_stg1.int","conc_m_4wpi_stg1.int",
    "conc_f_4wpi_stg2.int","conc_m_4wpi_stg2.int","conc_f_4wpi_stg3.int","conc_m_4wpi_stg3.int",
    "conc_f_4wpi_stg4.int","conc_m_4wpi_stg4.int","conc_f_6wpi_rest.int","conc_m_6wpi_rest.int",
    "conc_f_6wpi_stg1.int","conc_m_6wpi_stg1.int","conc_f_6wpi_stg2.int","conc_m_6wpi_stg2.int",
    "conc_f_6wpi_stg3.int","conc_m_6wpi_stg3.int","conc_f_6wpi_stg4.int","conc_m_6wpi_stg4.int",
    "conc_f_8wpi_rest.int","conc_m_8wpi_rest.int","conc_f_8wpi_stg1.int","conc_m_8wpi_stg1.int",
    "conc_f_8wpi_stg2.int","conc_m_8wpi_stg2.int","conc_f_8wpi_stg3.int","conc_m_8wpi_stg3.int",
    "conc_f_8wpi_stg4.int","conc_m_8wpi_stg4.int","mu_gr_sex_tp_st","sig_gr_sex_tp_st",
    "mu_id","sig_id","sigma")
  
  pred_df <- as.data.frame(matrix(NA,nrow=1000,ncol=70))
  colnames(pred_df) <- c("ctl_f_bl_rest","ctl_m_bl_rest","ctl_f_bl_stg1","ctl_m_bl_stg1",
      "ctl_f_bl_stg2","ctl_m_bl_stg2","ctl_f_bl_stg3","ctl_m_bl_stg3","ctl_f_bl_stg4",
      "ctl_m_bl_stg4","conc_f_1wpi_rest","conc_m_1wpi_rest","conc_f_1wpi_stg1",
      "conc_m_1wpi_stg1","conc_f_1wpi_stg2","conc_m_1wpi_stg2","conc_f_1wpi_stg3",
      "conc_m_1wpi_stg3","conc_f_1wpi_stg4","conc_m_1wpi_stg4","conc_f_2wpi_rest",
      "conc_m_2wpi_rest","conc_f_2wpi_stg1","conc_m_2wpi_stg1","conc_f_2wpi_stg2",
      "conc_m_2wpi_stg2","conc_f_2wpi_stg3","conc_m_2wpi_stg3","conc_f_2wpi_stg4",
      "conc_m_2wpi_stg4","conc_f_3wpi_rest","conc_m_3wpi_rest","conc_f_3wpi_stg1",
      "conc_m_3wpi_stg1","conc_f_3wpi_stg2","conc_m_3wpi_stg2","conc_f_3wpi_stg3",
      "conc_m_3wpi_stg3","conc_f_3wpi_stg4","conc_m_3wpi_stg4","conc_f_4wpi_rest",
      "conc_m_4wpi_rest","conc_f_4wpi_stg1","conc_m_4wpi_stg1","conc_f_4wpi_stg2",
      "conc_m_4wpi_stg2","conc_f_4wpi_stg3","conc_m_4wpi_stg3","conc_f_4wpi_stg4",
      "conc_m_4wpi_stg4","conc_f_6wpi_rest","conc_m_6wpi_rest","conc_f_6wpi_stg1",
      "conc_m_6wpi_stg1","conc_f_6wpi_stg2","conc_m_6wpi_stg2","conc_f_6wpi_stg3",
      "conc_m_6wpi_stg3","conc_f_6wpi_stg4","conc_m_6wpi_stg4","conc_f_8wpi_rest",
      "conc_m_8wpi_rest","conc_f_8wpi_stg1","conc_m_8wpi_stg1","conc_f_8wpi_stg2",
      "conc_m_8wpi_stg2","conc_f_8wpi_stg3","conc_m_8wpi_stg3","conc_f_8wpi_stg4",
      "conc_m_8wpi_stg4")
  sample_num <- sample(1:4000,1000,replace=FALSE)

  for (i in 1:length(sample_num)) {
    extracted_row <- extracted_samples[sample_num[i],]
    b_id <- rnorm(1,mean=extracted_row$mu_id,sd=extracted_row$sig_id)
    pred_df$ctl_f_bl_rest[i]  <- rstudent_t(1,df=extracted_row$nu,mu=(extracted_row$ctl+extracted_row$female+extracted_row$bl+extracted_row$rest+extracted_row$ctl_f_bl_rest.int+b_id),sigma=extracted_row$sigma)
    pred_df$ctl_m_bl_rest[i]  <- rstudent_t(1,df=extracted_row$nu,mu=(extracted_row$ctl+extracted_row$male+extracted_row$bl+extracted_row$rest+extracted_row$ctl_m_bl_rest.int+b_id),sigma=extracted_row$sigma)
    pred_df$ctl_f_bl_stg1[i] <- rstudent_t(1,df=extracted_row$nu,mu=(extracted_row$ctl+extracted_row$female+extracted_row$bl+extracted_row$stg1+extracted_row$ctl_f_bl_stg1.int+b_id),sigma=extracted_row$sigma)
    pred_df$ctl_m_bl_stg1[i] <- rstudent_t(1,df=extracted_row$nu,mu=(extracted_row$ctl+extracted_row$male+extracted_row$bl+extracted_row$stg1+extracted_row$ctl_m_bl_stg1.int+b_id),sigma=extracted_row$sigma)
    pred_df$ctl_f_bl_stg2[i]  <- rstudent_t(1,df=extracted_row$nu,mu=(extracted_row$ctl+extracted_row$female+extracted_row$bl+extracted_row$stg2+extracted_row$ctl_f_bl_stg2.int+b_id),sigma=extracted_row$sigma)
    pred_df$ctl_m_bl_stg2[i] <- rstudent_t(1,df=extracted_row$nu,mu=(extracted_row$ctl+extracted_row$male+extracted_row$bl+extracted_row$stg2+extracted_row$ctl_m_bl_stg2.int+b_id),sigma=extracted_row$sigma)
    pred_df$ctl_f_bl_stg3[i] <- rstudent_t(1,df=extracted_row$nu,mu=(extracted_row$ctl+extracted_row$female+extracted_row$bl+extracted_row$stg3+extracted_row$ctl_f_bl_stg3.int+b_id),sigma=extracted_row$sigma)
    pred_df$ctl_m_bl_stg3[i] <- rstudent_t(1,df=extracted_row$nu,mu=(extracted_row$ctl+extracted_row$male+extracted_row$bl+extracted_row$stg3+extracted_row$ctl_m_bl_stg3.int+b_id),sigma=extracted_row$sigma)
    pred_df$ctl_f_bl_stg4[i] <- rstudent_t(1,df=extracted_row$nu,mu=(extracted_row$ctl+extracted_row$female+extracted_row$bl+extracted_row$stg4+extracted_row$ctl_f_bl_stg4.int+b_id),sigma=extracted_row$sigma)
    pred_df$ctl_m_bl_stg4[i] <- rstudent_t(1,df=extracted_row$nu,mu=(extracted_row$ctl+extracted_row$male+extracted_row$bl+extracted_row$stg4+extracted_row$ctl_m_bl_stg4.int+b_id),sigma=extracted_row$sigma)
    
    pred_df$conc_f_1wpi_rest[i] <- rstudent_t(1,df=extracted_row$nu,mu=(extracted_row$conc+extracted_row$female+extracted_row$onewpi+extracted_row$rest+extracted_row$conc_f_1wpi_rest.int+b_id),sigma=extracted_row$sigma)
    pred_df$conc_m_1wpi_rest[i] <- rstudent_t(1,df=extracted_row$nu,mu=(extracted_row$conc+extracted_row$male+extracted_row$onewpi+extracted_row$rest+extracted_row$conc_m_1wpi_rest.int+b_id),sigma=extracted_row$sigma)
    pred_df$conc_f_1wpi_stg1[i] <- rstudent_t(1,df=extracted_row$nu,mu=(extracted_row$conc+extracted_row$female+extracted_row$onewpi+extracted_row$stg1+extracted_row$conc_f_1wpi_stg1.int+b_id),sigma=extracted_row$sigma)
    pred_df$conc_m_1wpi_stg1[i] <- rstudent_t(1,df=extracted_row$nu,mu=(extracted_row$conc+extracted_row$male+extracted_row$onewpi+extracted_row$stg1+extracted_row$conc_m_1wpi_stg1.int+b_id),sigma=extracted_row$sigma)
    pred_df$conc_f_1wpi_stg2[i] <- rstudent_t(1,df=extracted_row$nu,mu=(extracted_row$conc+extracted_row$female+extracted_row$onewpi+extracted_row$stg2+extracted_row$conc_f_1wpi_stg2.int+b_id),sigma=extracted_row$sigma)
    pred_df$conc_m_1wpi_stg2[i] <- rstudent_t(1,df=extracted_row$nu,mu=(extracted_row$conc+extracted_row$male+extracted_row$onewpi+extracted_row$stg2+extracted_row$conc_m_1wpi_stg2.int+b_id),sigma=extracted_row$sigma)
    pred_df$conc_f_1wpi_stg3[i] <- rstudent_t(1,df=extracted_row$nu,mu=(extracted_row$conc+extracted_row$female+extracted_row$onewpi+extracted_row$stg3+extracted_row$conc_f_1wpi_stg3.int+b_id),sigma=extracted_row$sigma)
    pred_df$conc_m_1wpi_stg3[i] <- rstudent_t(1,df=extracted_row$nu,mu=(extracted_row$conc+extracted_row$male+extracted_row$onewpi+extracted_row$stg3+extracted_row$conc_m_1wpi_stg3.int+b_id),sigma=extracted_row$sigma)
    pred_df$conc_f_1wpi_stg4[i] <- rstudent_t(1,df=extracted_row$nu,mu=(extracted_row$conc+extracted_row$female+extracted_row$onewpi+extracted_row$stg4+extracted_row$conc_f_1wpi_stg4.int+b_id),sigma=extracted_row$sigma)
