hr_real_func <- function(samples,variable) {
  colnames(samples) <- c("nu","ctl","conc","male","female","bl","onewpi","twowpi",
    "threewpi","fourwpi","sixwpi","eightwpi","rest","stg1","stg2","stg3","stg4",
    "ctl_f_bl_rest.int","ctl_m_bl_rest.int","ctl_f_bl_stg1.int","ctl_m_bl_stg1.int",
    "ctl_f_bl_stg2.int","ctl_m_bl_stg2.int","ctl_f_bl_stg3.int","ctl_m_bl_stg3.int",
    "ctl_f_bl_stg4.int","ctl_m_bl_stg4.int","conc_f_1wpi_rest.int","conc_m_1wpi_rest.int",
    "conc_f_1wpi_stg1.int","conc_m_1wpi_stg1.int","conc_f_1wpi_stg2.int","conc_m_1wpi_stg2.int",
    "conc_f_1wpi_stg3.int","conc_m_1wpi_stg3.int","conc_f_1wpi_stg4.int","conc_m_1wpi_stg4.int",
    "conc_f_2wpi_rest.int","conc_m_2wpi_rest.int","conc_f_2wpi_stg1.int","conc_m_2wpi_stg1.int",
    "conc_f_2wpi_stg2.int","conc_m_2wpi_stg2.int","conc_f_2wpi_stg3.int","conc_m_2wpi_stg3.int",
    "conc_f_2wpi_stg4.int","conc_m_2wpi_stg4.int","conc_f_3wpi_rest.int","conc_m_3wpi_rest.int",
    "conc_f_3wpi_stg1.int","conc_m_3wpi_stg1.int","conc_f_3wpi_stg2.int","conc_m_3wpi_stg2.int",
    "conc_f_3wpi_stg3.int","conc_m_3wpi_stg3.int","conc_f_3wpi_stg4.int","conc_m_3wpi_stg4.int",
    "conc_f_4wpi_rest.int","conc_m_4wpi_rest.int","conc_f_4wpi_stg1.int","conc_m_4wpi_stg1.int",
    "conc_f_4wpi_stg2.int","conc_m_4wpi_stg2.int","conc_f_4wpi_stg3.int","conc_m_4wpi_stg3.int",
    "conc_f_4wpi_stg4.int","conc_m_4wpi_stg4.int","conc_f_6wpi_rest.int","conc_m_6wpi_rest.int",
    "conc_f_6wpi_stg1.int","conc_m_6wpi_stg1.int","conc_f_6wpi_stg2.int","conc_m_6wpi_stg2.int",
    "conc_f_6wpi_stg3.int","conc_m_6wpi_stg3.int","conc_f_6wpi_stg4.int","conc_m_6wpi_stg4.int",
      "conc_f_8wpi_rest.int","conc_m_8wpi_rest.int","conc_f_8wpi_stg1.int","conc_m_8wpi_stg1.int",
      "conc_f_8wpi_stg2.int","conc_m_8wpi_stg2.int","conc_f_8wpi_stg3.int","conc_m_8wpi_stg3.int",
      "conc_f_8wpi_stg4.int","conc_m_8wpi_stg4.int","mu_gr_sex_tp_st","sig_gr_sex_tp_st",
     "mu_id","sig_id","sigma")
  #Creating the b_id parameter
  samples$b_id <- NA
  for (i in 1:length(samples$b_id)) {
    samples$b_id[i] <- rnorm(1,mean=samples$mu_id[i],sd=samples$sig_id[i])
  }
  
  samples$ctl_f_bl_rest  <- samples$ctl+samples$female+samples$bl+samples$rest+samples$ctl_f_bl_rest.int
  samples$ctl_m_bl_rest  <- samples$ctl+samples$male+samples$bl+samples$rest+samples$ctl_m_bl_rest.int
  samples$ctl_f_bl_stg1 <- samples$ctl+samples$female+samples$bl+samples$stg1+samples$ctl_f_bl_stg1.int
  samples$ctl_m_bl_stg1 <- samples$ctl+samples$male+samples$bl+samples$stg1+samples$ctl_m_bl_stg1.int
  samples$ctl_f_bl_stg2  <- samples$ctl+samples$female+samples$bl+samples$stg2+samples$ctl_f_bl_stg2.int
  samples$ctl_m_bl_stg2 <- samples$ctl+samples$male+samples$bl+samples$stg2+samples$ctl_m_bl_stg2.int
  samples$ctl_f_bl_stg3 <- samples$ctl+samples$female+samples$bl+samples$stg3+samples$ctl_f_bl_stg3.int
  samples$ctl_m_bl_stg3 <- samples$ctl+samples$male+samples$bl+samples$stg3+samples$ctl_m_bl_stg3.int
  samples$ctl_f_bl_stg4 <- samples$ctl+samples$female+samples$bl+samples$stg4+samples$ctl_f_bl_stg4.int
  samples$ctl_m_bl_stg4 <- samples$ctl+samples$male+samples$bl+samples$stg4+samples$ctl_m_bl_stg4.int
  
  samples$conc_f_1wpi_rest <- samples$conc+samples$female+samples$onewpi+samples$rest+samples$conc_f_1wpi_rest.int 
  samples$conc_m_1wpi_rest <- samples$conc+samples$male+samples$onewpi+samples$rest+samples$conc_m_1wpi_rest.int
  samples$conc_f_1wpi_stg1 <- samples$conc+samples$female+samples$onewpi+samples$stg1+samples$conc_f_1wpi_stg1.int
  samples$conc_m_1wpi_stg1 <- samples$conc+samples$male+samples$onewpi+samples$stg1+samples$conc_m_1wpi_stg1.int
  samples$conc_f_1wpi_stg2 <- samples$conc+samples$female+samples$onewpi+samples$stg2+samples$conc_f_1wpi_stg2.int
  samples$conc_m_1wpi_stg2 <- samples$conc+samples$male+samples$onewpi+samples$stg2+samples$conc_m_1wpi_stg2.int
  samples$conc_f_1wpi_stg3 <- samples$conc+samples$female+samples$onewpi+samples$stg3+samples$conc_f_1wpi_stg3.int
  samples$conc_m_1wpi_stg3 <- samples$conc+samples$male+samples$onewpi+samples$stg3+samples$conc_m_1wpi_stg3.int
  samples$conc_f_1wpi_stg4 <- samples$conc+samples$female+samples$onewpi+samples$stg4+samples$conc_f_1wpi_stg4.int
