  samples$conc_f_2wpi_stg1 <- samples$conc+samples$female+samples$twowpi+samples$stg1+samples$conc_f_2wpi_stg1.int
  samples$conc_m_2wpi_stg1 <- samples$conc+samples$male+samples$twowpi+samples$stg1+samples$conc_m_2wpi_stg1.int
  samples$conc_f_2wpi_stg2 <- samples$conc+samples$female+samples$twowpi+samples$stg2+samples$conc_f_2wpi_stg2.int
