  samples$conc_f_2wpi_stg3 <- samples$conc+samples$female+samples$twowpi+samples$stg3+samples$conc_f_2wpi_stg3.int
  samples$conc_m_2wpi_stg3 <- samples$conc+samples$male+samples$twowpi+samples$stg3+samples$conc_m_2wpi_stg3.int
  samples$conc_f_2wpi_stg4 <- samples$conc+samples$female+samples$twowpi+samples$stg4+samples$conc_f_2wpi_stg4.int
  samples$conc_m_2wpi_stg4 <- samples$conc+samples$male+samples$twowpi+samples$stg4+samples$conc_m_2wpi_stg4.int
  
