post_pc_hr_stu_t_func <- function(extracted_samples, variable) {
  extracted_samples <- extracted_samples[c(1:17,375:444,18,19,231:233)]
  colnames(extracted_samples) <- c("nu","ctl","conc","male","female","bl","onewpi","twowpi",
