                                   "conc_f_1wpi_stg3.int","conc_m_1wpi_stg3.int","conc_f_1wpi_stg4.int","conc_m_1wpi_stg4.int",
                                   "conc_f_2wpi_rest.int","conc_m_2wpi_rest.int","conc_f_2wpi_stg1.int","conc_m_2wpi_stg1.int",
                                   "conc_f_2wpi_stg2.int","conc_m_2wpi_stg2.int","conc_f_2wpi_stg3.int","conc_m_2wpi_stg3.int",
                                   "conc_f_2wpi_stg4.int","conc_m_2wpi_stg4.int","conc_f_3wpi_rest.int","conc_m_3wpi_rest.int",
                                   "conc_f_3wpi_stg1.int","conc_m_3wpi_stg1.int","conc_f_3wpi_stg2.int","conc_m_3wpi_stg2.int",
                                   "conc_f_3wpi_stg3.int","conc_m_3wpi_stg3.int","conc_f_3wpi_stg4.int","conc_m_3wpi_stg4.int",
                                   "conc_f_4wpi_rest.int","conc_m_4wpi_rest.int","conc_f_4wpi_stg1.int","conc_m_4wpi_stg1.int",
                                   "conc_f_4wpi_stg2.int","conc_m_4wpi_stg2.int","conc_f_4wpi_stg3.int","conc_m_4wpi_stg3.int",
                                   "conc_f_4wpi_stg4.int","conc_m_4wpi_stg4.int","conc_f_6wpi_rest.int","conc_m_6wpi_rest.int",
                                   "conc_f_6wpi_stg1.int","conc_m_6wpi_stg1.int","conc_f_6wpi_stg2.int","conc_m_6wpi_stg2.int",
                                   "conc_f_6wpi_stg3.int","conc_m_6wpi_stg3.int","conc_f_6wpi_stg4.int","conc_m_6wpi_stg4.int",
                                   "conc_f_8wpi_rest.int","conc_m_8wpi_rest.int","conc_f_8wpi_stg1.int","conc_m_8wpi_stg1.int",
                                   "conc_f_8wpi_stg2.int","conc_m_8wpi_stg2.int","conc_f_8wpi_stg3.int","conc_m_8wpi_stg3.int",
                                   "conc_f_8wpi_stg4.int","conc_m_8wpi_stg4.int","mu_gr_sex_tp_st","sig_gr_sex_tp_st",
                                   "mu_id","sig_id","sigma")
  
  pred_df <- as.data.frame(matrix(NA,nrow=1000,ncol=70))
  colnames(pred_df) <- c("ctl_f_bl_rest","ctl_m_bl_rest","ctl_f_bl_stg1","ctl_m_bl_stg1",
                         "ctl_f_bl_stg2","ctl_m_bl_stg2","ctl_f_bl_stg3","ctl_m_bl_stg3","ctl_f_bl_stg4",
                         "ctl_m_bl_stg4","conc_f_1wpi_rest","conc_m_1wpi_rest","conc_f_1wpi_stg1",
                         "conc_m_1wpi_stg1","conc_f_1wpi_stg2","conc_m_1wpi_stg2","conc_f_1wpi_stg3",
