#Prior HR
dat_prior_hr <- list(N = length(mean_hr_df_wide$new_id),
                     N_ids = length(unique(mean_hr_df_wide$new_id)),
                     group = as.integer(mean_hr_df_wide$group),
                     sex = as.integer(mean_hr_df_wide$sex),
                     timepoint = as.integer(mean_hr_df_wide$time_point),
                     stage = as.integer(mean_hr_df_wide$stage),
                     gr_sex_tp_st = mean_hr_df_wide$gr_sex_tp_st_int,
                     id = as.integer(mean_hr_df_wide$new_id),
                     hr = z_score(mean_hr_df_wide$mean_hr)*0)
str(dat_prior_hr)
hr_prior_model <- sampling(met_hr_prior_mod, dat = dat_prior_hr)
precis(hr_prior_model,depth=2)
saveRDS(hr_prior_model, "hr_prior_model.rds")
hr_prior_model <- readRDS("hr_prior_model.rds")

#Extracting samples - change the model based on which one you are choosing
hr_prior_samples <- as.data.frame(rstan::extract(hr_prior_model))

#check chains
traceplot(hr_prior_model, pars = c('b_group'))
traceplot(hr_prior_model, pars = c('b_sex'))
traceplot(hr_prior_model, pars = c('b_time_point'))
traceplot(hr_prior_model, pars = c('b_stage'))

colnames(hr_prior_samples)
hr_func(hr_prior_samples,mean_hr_df_wide$mean_hr)
hr_prior_samples <- samples
rm(samples)
colnames(hr_prior_samples)
colnames(hr_prior_samples)[c(1,88:92)] <- c("nu","mu_gr_sex_tp_st","sig_gr_sex_tp_st",
                                            "mu_id","sig_id","sigma")

