#BL
colnames(hr_prior_samples)
plot_hr_prior_bl <- rbind.data.frame(gather(hr_prior_samples[c(180:189)]))
plot_hr_prior_bl$stage <- c(rep(" Pre-MET",8000),rep("MET 1",8000),rep("MET 2",8000),
                                  rep("MET 3",8000),rep("MET 4",8000))
plot_hr_prior_bl$group <- rep(c(rep("CTL Female",4000),rep("CTL Male",4000)),5)
table(plot_hr_prior_bl$group)
table(plot_hr_prior_bl$key)

fig_hr_prior_bl <- plot_hr_prior_bl %>%
  ggplot(aes(y = stage,x = value,fill = group)) + 
  theme_classic()+
  theme(strip.text.x = element_text(face = 'bold',size = 10),
        axis.title.x = element_text(size = 9,face = 'bold'),
        axis.title.y = element_blank(),
        axis.text.y = element_text(face = 'bold',size = 9),
        legend.text = element_text(size = 8),
        legend.title = element_blank(),
        legend.position = c(0.9,.07),
        legend.spacing.y = unit(0, "pt"),
        legend.spacing.x = unit(0, "pt"),
        legend.box.margin=margin(-0.2,-0.2,-0.2,-0.2),
        axis.text.x = element_text(face = 'bold',size = 8))+
  scale_fill_manual("Group",values = c("violetred1","royalblue1")) +xlim(30,170)+
  stat_halfeye(.width = c(0.70,0.90),alpha = 0.7) +
  xlab("Heart Rate (beats per minute)") + ggtitle("Average HR (BL) - Priors")
fig_hr_prior_bl

