  ####Simulation Model####
#Loading in data
dat_sim_hr <- list(N = length(mean_hr_df_wide$new_id),
                     N_ids = length(unique(mean_hr_df_wide$new_id)),
                     group = as.integer(mean_hr_df_wide$group),
                     sex = as.integer(mean_hr_df_wide$sex),
                     timepoint = as.integer(mean_hr_df_wide$time_point),
                     stage = as.integer(mean_hr_df_wide$stage),
                     gr_sex_tp_st = mean_hr_df_wide$gr_sex_tp_st_int,
                     id = as.integer(mean_hr_df_wide$new_id),
                     hr = mean_hr_df_wide$simulated_data)#mean hr
str(dat_sim_hr)
hr_sim_model <- sampling(met_hr_mod, dat = dat_sim_hr)
saveRDS(hr_sim_model, "hr_sim_model.rds")
hr_sim_model <- readRDS("hr_sim_model.rds")
hr_sim_samples <- as.data.frame(rstan::extract(hr_sim_model))
precis(hr_sim_model,depth=2)

hr_sim_samples <- as.data.frame(rstan::extract(hr_sim_model))
colnames(hr_sim_samples)
hr_sim_samples <- hr_sim_samples[c(1:17,375:444,18,19,231:233)]
colnames(hr_sim_samples)

#check chains
traceplot(hr_sim_model, pars = c('b_group'))
traceplot(hr_sim_model, pars = c('b_sex'))
traceplot(hr_sim_model, pars = c('b_time_point'))
traceplot(hr_sim_model, pars = c('b_stage'))

hr_real_func(hr_sim_samples,mean_hr_df_wide$mean_hr)
hr_sim_samples <- samples
rm(samples)
apply(hr_sim_samples[c(164:249)],2,summary)
colnames(hr_sim_samples)[c(1,88:93)] <- c("nu","mu_gr_sex_tp_st",
         "sig_gr_sex_tp_st","mu_id","sig_id","sigma","b_id")
write.csv(hr_sim_samples,"hr_sim_samples.csv")

