#Real HR
dat_real_hr <- list(N = length(mean_hr_df_wide$new_id),
                     N_ids = length(unique(mean_hr_df_wide$new_id)),
                     group = as.integer(mean_hr_df_wide$group),
                     sex = as.integer(mean_hr_df_wide$sex),
                     timepoint = as.integer(mean_hr_df_wide$time_point),
                     stage = as.integer(mean_hr_df_wide$stage),
                     gr_sex_tp_st = mean_hr_df_wide$gr_sex_tp_st_int,
                     id = as.integer(mean_hr_df_wide$new_id),
                     hr = mean_hr_df_wide$mean_hr_zscore) #mean hr
str(dat_real_hr)
#Running model
#Adding in the non-centered parameterization, first tried to put in an adaptive prior but it didn't work (divergent issues)
hr_post_model <- sampling(met_hr_mod, dat = dat_real_hr)
precis(hr_post_model,depth=2)
saveRDS(hr_post_model, "hr_post_model.rds")
hr_post_model <- readRDS("hr_post_model.rds")
loo_hr_mod <- loo(hr_post_model)
plot(loo_hr_mod,diagnostic = c("k"),label_points = FALSE,main = "PSIS diagnostic plot")

hr_post_samples <- as.data.frame(rstan::extract(hr_post_model))
colnames(hr_post_samples)
hr_post_samples <- hr_post_samples[c(1:17,375:444,18,19,231:233)]
colnames(hr_post_samples)

#check chains
traceplot(hr_post_model, pars = c('b_group'))
traceplot(hr_post_model, pars = c('b_sex'))
traceplot(hr_post_model, pars = c('b_time_point'))
traceplot(hr_post_model, pars = c('b_stage'))

hr_real_func(hr_post_samples,mean_hr_df_wide$mean_hr)
hr_post_samples <- samples
rm(samples)
colnames(hr_post_samples)
apply(hr_post_samples[c(164:249)],2,summary)

write.csv(hr_post_samples,"hr_post_samples.csv")
