#Real Maximum HR
dat_real_maxhr <- list(N = length(max_hr_df_wide$new_id),
                    N_ids = length(unique(max_hr_df_wide$new_id)),
                    group = as.integer(max_hr_df_wide$group),
                    sex = as.integer(max_hr_df_wide$sex),
                    timepoint = as.integer(max_hr_df_wide$time_point),
                    stage = as.integer(max_hr_df_wide$stage),
                    gr_sex_tp_st = max_hr_df_wide$gr_sex_tp_st_int,
                    id = as.integer(max_hr_df_wide$new_id),
                    hr = max_hr_df_wide$max_hr_zscore) #max hr
str(dat_real_maxhr)
#Running model
maxhr_post_model <- sampling(met_maxhr_mod, dat = dat_real_maxhr)
saveRDS(maxhr_post_model, "maxhr_post_model.rds")
maxhr_post_model <- readRDS("maxhr_post_model.rds")
precis(maxhr_post_model,depth=2)

loo_maxhr_mod <- loo(maxhr_post_model)
plot(loo_maxhr_mod,diagnostic = c("k"),label_points = FALSE,main = "PSIS diagnostic plot")
print(which(loo_maxhr_mod$diagnostics$pareto_k > 0.7))

#Extracting samples
maxhr_post_samples <- as.data.frame(rstan::extract(maxhr_post_model))
colnames(maxhr_post_samples)
maxhr_post_samples <- maxhr_post_samples[c(1:17,375:444,18,19,231:233)]
colnames(maxhr_post_samples)

#check chains
traceplot(maxhr_post_model, pars = c('b_group'))
traceplot(maxhr_post_model, pars = c('b_sex'))
traceplot(maxhr_post_model, pars = c('b_time_point'))
traceplot(maxhr_post_model, pars = c('b_stage'))

hr_real_func(maxhr_post_samples,max_hr_df_wide$max_hr)
maxhr_post_samples <- samples
rm(samples)
colnames(maxhr_post_samples)
apply(maxhr_post_samples[c(164:249)],2,summary)

write.csv(maxhr_post_samples,"maxhr_post_samples.csv")

