  #####Symptoms Set-Up#####
colnames(bl_conc6tp_data)
sx_analyses_all <- bl_conc6tp_data[c(1,4,22,396,329,333,337,344,348,352,360,365,370,377,381,389)]
colnames(sx_analyses_all)
sx_analyses_all[,c(4:16)] <- lapply(4:ncol(sx_analyses_all), function(x) as.numeric(sx_analyses_all[[x]]))
colnames(sx_analyses_all)

#Creating an ID for the columns
sx_analyses_all$new_id <- substr(sx_analyses_all$unique_id,start=5,stop=7)
sx_analyses_all$new_id <- sub("^0+", "", sx_analyses_all$new_id)
length(unique(sx_analyses_all$new_id))
sx_analyses_all$new_id <- as.numeric(sx_analyses_all$new_id)
sx_analyses_all$new_id <- match(sx_analyses_all$new_id, unique(sx_analyses_all$new_id))
unique(sx_analyses_all$new_id)

#Now creating a group ID
unique(sx_analyses_all$redcap_event_name)
sx_analyses_all$group <- ifelse(sx_analyses_all$redcap_event_name == "Concussion Week 1",2,
    ifelse(sx_analyses_all$redcap_event_name == "Concussion Week 2",2,
    ifelse(sx_analyses_all$redcap_event_name == "Concussion Week 3",2,
    ifelse(sx_analyses_all$redcap_event_name == "Concussion Week 4",2,
    ifelse(sx_analyses_all$redcap_event_name == "Concussion Week 6",2,
    ifelse(sx_analyses_all$redcap_event_name == "Concussion Week 8",2,1))))))

unique(sx_analyses_all$redcap_event_name)
sx_analyses_all$time_point <- ifelse(sx_analyses_all$redcap_event_name == " Healthy",1,
    ifelse(sx_analyses_all$redcap_event_name == "Concussion Week 1",2,
    ifelse(sx_analyses_all$redcap_event_name == "Concussion Week 2",3,
    ifelse(sx_analyses_all$redcap_event_name == "Concussion Week 3",4,
    ifelse(sx_analyses_all$redcap_event_name == "Concussion Week 4",5,
    ifelse(sx_analyses_all$redcap_event_name == "Concussion Week 6",6,7))))))

colnames(sx_analyses_all)
