#Prior Sx
dat_prior_sx <- list(N = length(sx_df_wide$new_id),
                     N_ids = length(unique(sx_df_wide$new_id)),
                     group = as.integer(sx_df_wide$group),
                     sex = as.integer(sx_df_wide$sex),
                     timepoint = as.integer(sx_df_wide$time_point),
                     task = as.integer(sx_df_wide$task),
                     gr_sex_tp_ta = sx_df_wide$gr_sex_tp_ta_int,
                     id = as.integer(sx_df_wide$new_id),
                     sx = (sx_df_wide$sx)*0) #symptoms
str(dat_prior_sx)

#Running model
sx_prior_model <- sampling(sx_prior_mod, dat = dat_prior_sx)
precis(sx_prior_model,depth=2)
saveRDS(sx_prior_model, "sx_prior_model.rds")
sx_prior_model <- readRDS("sx_prior_model.rds")

prior_sx_samples <- as.data.frame(rstan::extract(sx_prior_model))
colnames(prior_sx_samples)

#Running function
sx_func(prior_sx_samples)
sx_prior_samples <- samples
rm(samples)
colnames(sx_prior_samples)
apply(sx_prior_samples[c(392:573)],2,summary)

  ####Sx Prior Graphs####
#Now going to create graphs for the priors at all time points
colnames(sx_prior_samples)
plot_sx_prior_bl <- rbind.data.frame(gather(sx_prior_samples[c(392:417)]))
plot_sx_prior_bl$task <- c(rep("Initial",8000),rep("Stg. 1 - 20 Squats",8000),
   rep("Stg. 1 - 20 Lunges",8000),rep("Stg. 1 - 20 Hip Hinges",8000),
   rep("Stg. 2 - 10 Squats",8000),rep("Stg. 2 - 10 Lunges",8000),
   rep("Stg. 2 - 10 Hip Hinges",8000),rep("Stg. 3 - 20 Squats + COWAT",8000),
   rep("Stg. 3 - 20 Lunges + COWAT",8000),rep("Stg. 3 - 20 Hip Hinges + COWAT",8000),
   rep("Stg. 4 - Drop + Choice Lateral Jump",8000),rep("Stg. 4 - Jump-Overs",8000),
   rep("Stg. 4 - Jump-Overs + Recall",8000))
plot_sx_prior_bl$group <- rep(c(rep("CTL Female",4000),rep("CTL Male",4000)),13)

fig_sx_prior_bl <- plot_sx_prior_bl %>%
  ggplot(aes(y = task,x = value,fill = group)) + 
  theme_classic()+
  theme(strip.text.x = element_text(face = 'bold',size = 10),
        axis.title.x = element_text(size = 9,face = 'bold'),
        axis.title.y = element_blank(),
        axis.text.y = element_text(face = 'bold',size = 7),
        legend.text = element_text(size = 8),
        legend.title = element_blank(),
        legend.position = c(0.9,.15),
        legend.spacing.y = unit(0, "pt"),
        legend.spacing.x = unit(0, "pt"),
        legend.box.margin=margin(-0.2,-0.2,-0.2,-0.2),
        axis.text.x = element_text(face = 'bold',size = 8))+
  scale_fill_manual("Group",values = c("violetred1","royalblue1")) +xlim(0,40)+
  stat_halfeye(.width = c(0.70,0.90),alpha = 0.7) +
  xlab("Symptom Severity Score (/162)") + ggtitle("Symptoms - Priors (BL)")
fig_sx_prior_bl

