post_sx_table <- 
  tbl_strata(posterior_sx, 
             strata = 'Group',
             .tbl_fun =
               ~ .x %>%
               tbl_summary(by = `Sex`, missing = "no",
                           digits=list(
                             "Initial Symptom Severity Score" ~ 0,
                             "20 Hip Hinges" ~ 0,
                             "20 Lunges" ~ 0,
                             "20 Squats" ~ 0,
                             "10 Hip Hinges" ~ 0,
                             "10 Lunges" ~ 0,
                             "10 Squats" ~ 0,
                             "20 Hip Hinges + COWAT" ~ 0,
                             "20 Lunges + COWAT" ~ 0,
                             "20 Squats + COWAT" ~ 0,
                             "Step Down + Choice Lateral Jump" ~ 0,
                             "Jump-Overs 1" ~ 0,
                             "Jump-Overs 2 with Delayed HVLT" ~ 0),
                           type = list("Initial Symptom Severity Score" ~ 'continuous',
                                       "20 Hip Hinges" ~ 'continuous',
                                       "20 Lunges" ~ 'continuous',
                                       "20 Squats" ~ 'continuous',
                                       "10 Hip Hinges" ~ 'continuous',
                                       "10 Lunges" ~ 'continuous',
                                       "10 Squats" ~ 'continuous',
                                       "20 Hip Hinges + COWAT" ~ 'continuous',
                                       "20 Lunges + COWAT" ~ 'continuous',
                                       "20 Squats + COWAT" ~ 'continuous',
                                       "Step Down + Choice Lateral Jump" ~ 'continuous',
                                       "Jump-Overs 1" ~ 'continuous',
                                       "Jump-Overs 2 with Delayed HVLT" ~ 'continuous'),
                           statistic = list(all_continuous() ~ "{mean} ({HDILow}, {HDIHigh})"))) %>%
  modify_caption("**MET - Symptoms Posterior**")%>%
  as_gt() %>%
  tab_row_group(label = "Pre-MET", id = "Pre-MET",rows = 1:1) %>%
  tab_row_group(label = "MET - Stage 1", id = "MET - Stage 1",rows = 2:4) %>% 
  tab_row_group(label = "MET - Stage 2", id = "MET - Stage 2",rows = 5:7) %>% 
  tab_row_group(label = "MET - Stage 3", id = "MET - Stage 3",rows = 8:10) %>%
  tab_row_group(label = "MET - Stage 4", id = "MET - Stage 4",rows = 11:13) %>%
  row_group_order(groups = c("Pre-MET","MET - Stage 1","MET - Stage 2","MET - Stage 3","MET - Stage 4"))%>%
  tab_style( style = cell_text(weight = "bold"),
             locations = cells_row_groups(groups= c("Pre-MET","MET - Stage 1","MET - Stage 2",
                                                    "MET - Stage 3","MET - Stage 4"))) %>%
  fmt(columns = everything(),
      fns = function(x) ifelse(x == "", "0 (0)", x))%>%
  tab_source_note(md(""))  %>%
  gt::tab_options(table.font.names = "Times New Roman")%>%
  gt::gtsave(filename = "post_sx_all.html")

