met1_tasks_prior_mod <- stan_model("met1_tasks_prior.stan")

met1_tasks_mod <- stan_model("met1_tasks.stan")

  ####All MET Tasks Functions####
met_tasks_func <- function(samples,variable) {
  samples <- samples[c(1:15,383:424,223:225,58,59)]
  colnames(samples) <- c("nu","ctl","conc","male","female","bl","onewpi","twowpi",
                         "threewpi","fourwpi","sixwpi","eightwpi","squats","lunges","gm","ctl_f_bl_squats.int",
                         "ctl_m_bl_squats.int","ctl_f_bl_lunges.int","ctl_m_bl_lunges.int","ctl_f_bl_gm.int",
                         "ctl_m_bl_gm.int","conc_f_1wpi_squats.int","conc_m_1wpi_squats.int",
                         "conc_f_1wpi_lunges.int","conc_m_1wpi_lunges.int","conc_f_1wpi_gm.int",
                         "conc_m_1wpi_gm.int","conc_f_2wpi_squats.int","conc_m_2wpi_squats.int",
                         "conc_f_2wpi_lunges.int","conc_m_2wpi_lunges.int","conc_f_2wpi_gm.int",
                         "conc_m_2wpi_gm.int","conc_f_3wpi_squats.int","conc_m_3wpi_squats.int",
                         "conc_f_3wpi_lunges.int","conc_m_3wpi_lunges.int","conc_f_3wpi_gm.int",
                         "conc_m_3wpi_gm.int","conc_f_4wpi_squats.int","conc_m_4wpi_squats.int",
                         "conc_f_4wpi_lunges.int","conc_m_4wpi_lunges.int","conc_f_4wpi_gm.int",
                         "conc_m_4wpi_gm.int","conc_f_6wpi_squats.int","conc_m_6wpi_squats.int",
                         "conc_f_6wpi_lunges.int","conc_m_6wpi_lunges.int","conc_f_6wpi_gm.int",
                         "conc_m_6wpi_gm.int","conc_f_8wpi_squats.int","conc_m_8wpi_squats.int",
                         "conc_f_8wpi_lunges.int","conc_m_8wpi_lunges.int","conc_f_8wpi_gm.int",
                         "conc_m_8wpi_gm.int","mu_id","sig_id","sigma","mu_gr_sex_tp_ta","sig_gr_sex_tp_ta")
  
  samples$ctl_f_bl_squats <- samples$ctl+samples$female+samples$bl+samples$squats+samples$ctl_f_bl_squats.int
  samples$ctl_m_bl_squats <- samples$ctl+samples$male+samples$bl+samples$squats+samples$ctl_m_bl_squats.int
  samples$ctl_f_bl_lunges <- samples$ctl+samples$female+samples$bl+samples$lunges+samples$ctl_f_bl_lunges.int
  samples$ctl_m_bl_lunges <- samples$ctl+samples$male+samples$bl+samples$lunges+samples$ctl_m_bl_lunges.int
  samples$ctl_f_bl_gm <- samples$ctl+samples$female+samples$bl+samples$gm+samples$ctl_f_bl_gm.int
  samples$ctl_m_bl_gm <- samples$ctl+samples$male+samples$bl+samples$gm+samples$ctl_m_bl_gm.int
  
  samples$conc_f_1wpi_squats <- samples$conc+samples$female+samples$onewpi+samples$squats+samples$conc_f_1wpi_squats.int
  samples$conc_m_1wpi_squats <- samples$conc+samples$male+samples$onewpi+samples$squats+samples$conc_m_1wpi_squats.int
  samples$conc_f_1wpi_lunges <- samples$conc+samples$female+samples$onewpi+samples$lunges+samples$conc_f_1wpi_lunges.int
  samples$conc_m_1wpi_lunges <- samples$conc+samples$male+samples$onewpi+samples$lunges+samples$conc_m_1wpi_lunges.int
  samples$conc_f_1wpi_gm <- samples$conc+samples$female+samples$onewpi+samples$gm+samples$conc_f_1wpi_gm.int
  samples$conc_m_1wpi_gm <- samples$conc+samples$male+samples$onewpi+samples$gm+samples$conc_m_1wpi_gm.int
  
  samples$conc_f_2wpi_squats <- samples$conc+samples$female+samples$twowpi+samples$squats+samples$conc_f_2wpi_squats.int
  samples$conc_m_2wpi_squats <- samples$conc+samples$male+samples$twowpi+samples$squats+samples$conc_m_2wpi_squats.int
  samples$conc_f_2wpi_lunges <- samples$conc+samples$female+samples$twowpi+samples$lunges+samples$conc_f_2wpi_lunges.int
  samples$conc_m_2wpi_lunges <- samples$conc+samples$male+samples$twowpi+samples$lunges+samples$conc_m_2wpi_lunges.int
  samples$conc_f_2wpi_gm <- samples$conc+samples$female+samples$twowpi+samples$gm+samples$conc_f_2wpi_gm.int
  samples$conc_m_2wpi_gm <- samples$conc+samples$male+samples$twowpi+samples$gm+samples$conc_m_2wpi_gm.int
  
  samples$conc_f_3wpi_squats <- samples$conc+samples$female+samples$threewpi+samples$squats+samples$conc_f_3wpi_squats.int
  samples$conc_m_3wpi_squats <- samples$conc+samples$male+samples$threewpi+samples$squats+samples$conc_m_3wpi_squats.int
  samples$conc_f_3wpi_lunges <- samples$conc+samples$female+samples$threewpi+samples$lunges+samples$conc_f_3wpi_lunges.int
  samples$conc_m_3wpi_lunges <- samples$conc+samples$male+samples$threewpi+samples$lunges+samples$conc_m_3wpi_lunges.int
  samples$conc_f_3wpi_gm <- samples$conc+samples$female+samples$threewpi+samples$gm+samples$conc_f_3wpi_gm.int
  samples$conc_m_3wpi_gm <- samples$conc+samples$male+samples$threewpi+samples$gm+samples$conc_m_3wpi_gm.int
  
  samples$conc_f_4wpi_squats <- samples$conc+samples$female+samples$fourwpi+samples$squats+samples$conc_f_4wpi_squats.int
  samples$conc_m_4wpi_squats <- samples$conc+samples$male+samples$fourwpi+samples$squats+samples$conc_m_4wpi_squats.int
  samples$conc_f_4wpi_lunges <- samples$conc+samples$female+samples$fourwpi+samples$lunges+samples$conc_f_4wpi_lunges.int
  samples$conc_m_4wpi_lunges <- samples$conc+samples$male+samples$fourwpi+samples$lunges+samples$conc_m_4wpi_lunges.int
  samples$conc_f_4wpi_gm <- samples$conc+samples$female+samples$fourwpi+samples$gm+samples$conc_f_4wpi_gm.int
  samples$conc_m_4wpi_gm <- samples$conc+samples$male+samples$fourwpi+samples$gm+samples$conc_m_4wpi_gm.int
  
  samples$conc_f_6wpi_squats <- samples$conc+samples$female+samples$sixwpi+samples$squats+samples$conc_f_6wpi_squats.int
  samples$conc_m_6wpi_squats <- samples$conc+samples$male+samples$sixwpi+samples$squats+samples$conc_m_6wpi_squats.int
  samples$conc_f_6wpi_lunges <- samples$conc+samples$female+samples$sixwpi+samples$lunges+samples$conc_f_6wpi_lunges.int
