  samples$conc_f_6wpi_gm <- samples$conc+samples$female+samples$sixwpi+samples$gm+samples$conc_f_6wpi_gm.int
  samples$conc_m_6wpi_gm <- samples$conc+samples$male+samples$sixwpi+samples$gm+samples$conc_m_6wpi_gm.int
  
  samples$conc_f_8wpi_squats <- samples$conc+samples$female+samples$eightwpi+samples$squats+samples$conc_f_8wpi_squats.int
  samples$conc_m_8wpi_squats <- samples$conc+samples$male+samples$eightwpi+samples$squats+samples$conc_m_8wpi_squats.int
  samples$conc_f_8wpi_lunges <- samples$conc+samples$female+samples$eightwpi+samples$lunges+samples$conc_f_8wpi_lunges.int
  samples$conc_m_8wpi_lunges <- samples$conc+samples$male+samples$eightwpi+samples$lunges+samples$conc_m_8wpi_lunges.int
  samples$conc_f_8wpi_gm <- samples$conc+samples$female+samples$eightwpi+samples$gm+samples$conc_f_8wpi_gm.int
  samples$conc_m_8wpi_gm <- samples$conc+samples$male+samples$eightwpi+samples$gm+samples$conc_m_8wpi_gm.int
  
  colnames(samples)
  samples[c(105:160)] <- apply(samples[c(2:15,63:104)],2,function(x) (x*sd(variable))+ 
                                mean(variable))
  colnames(samples) <- c(colnames(samples[c(1)]),paste(colnames(samples[c(2:57)]),"zscore",sep="_"),
                         colnames(samples[c(58:62)]),paste(colnames(samples[c(63:104)]),"zscore",sep="_"),
                         colnames(samples[c(2:15,63:104)]))
  apply(samples[c(105:160)],2,summary)
  assign("samples",samples,envir = .GlobalEnv)
}

