ppc_met3_tasks_stu_t_func <- function(extracted_samples, variable) {
  extracted_samples <- extracted_samples[c(1:15,379:420,60:65,221:223,58:59)]
  colnames(extracted_samples) <- c("nu","ctl","conc","male","female","bl","onewpi","twowpi",
                                   "threewpi","fourwpi","sixwpi","eightwpi","squats","lunges","gm","ctl_f_bl_squats.int",
                                   "ctl_m_bl_squats.int","ctl_f_bl_lunges.int","ctl_m_bl_lunges.int","ctl_f_bl_gm.int",
                                   "ctl_m_bl_gm.int","conc_f_1wpi_squats.int","conc_m_1wpi_squats.int",
                                   "conc_f_1wpi_lunges.int","conc_m_1wpi_lunges.int","conc_f_1wpi_gm.int",
                                   "conc_m_1wpi_gm.int","conc_f_2wpi_squats.int","conc_m_2wpi_squats.int",
                                   "conc_f_2wpi_lunges.int","conc_m_2wpi_lunges.int","conc_f_2wpi_gm.int",
                                   "conc_m_2wpi_gm.int","conc_f_3wpi_squats.int","conc_m_3wpi_squats.int",
                                   "conc_f_3wpi_lunges.int","conc_m_3wpi_lunges.int","conc_f_3wpi_gm.int",
                                   "conc_m_3wpi_gm.int","conc_f_4wpi_squats.int","conc_m_4wpi_squats.int",
                                   "conc_f_4wpi_lunges.int","conc_m_4wpi_lunges.int","conc_f_4wpi_gm.int",
                                   "conc_m_4wpi_gm.int","conc_f_6wpi_squats.int","conc_m_6wpi_squats.int",
                                   "conc_f_6wpi_lunges.int","conc_m_6wpi_lunges.int","conc_f_6wpi_gm.int",
                                   "conc_m_6wpi_gm.int","conc_f_8wpi_squats.int","conc_m_8wpi_squats.int",
                                   "conc_f_8wpi_lunges.int","conc_m_8wpi_lunges.int","conc_f_8wpi_gm.int",
                                   "conc_m_8wpi_gm.int","b_task_order.1","b_task_order.2","b_task_order.3",   
                                   "b_task_order.4","b_task_order.5","b_task_order.6","mu_id","sig_id","sigma",
                                   "mu_gr_sex_tp_ta","sig_gr_sex_tp_ta")
  
  pred_df <- as.data.frame(matrix(NA,nrow=1000,ncol=42))
  colnames(pred_df) <- c("ctl_f_bl_squats","ctl_m_bl_squats","ctl_f_bl_lunges",
                         "ctl_m_bl_lunges","ctl_f_bl_gm","ctl_m_bl_gm","conc_f_1wpi_squats",           
                         "conc_m_1wpi_squats","conc_f_1wpi_lunges","conc_m_1wpi_lunges",           
