  ####MET Stage 1 Tasks Set-Up####
#Putting it all together in a dataframe to use for analyses
colnames(met_perf_all)
met1_tasks_df_wide <- gather(met_perf_all[c(4:6)], key = 'task', value = 'comp_time')
met1_tasks_df_wide$new_id <- rep(met_perf_all$new_id,3)
met1_tasks_df_wide$sex <- rep(met_perf_all$Sex,3)
met1_tasks_df_wide$group <- rep(met_perf_all$group,3)
met1_tasks_df_wide$time_point <- rep(met_perf_all$time_point,3)
