#Simulations MET Completion Times
dat_sim_met1_tasks <- list(N = length(met1_tasks_df_wide$new_id),
      N_ids = length(unique(met1_tasks_df_wide$new_id)),
      group = as.integer(met1_tasks_df_wide$group),
      sex = as.integer(met1_tasks_df_wide$sex),
      timepoint = as.integer(met1_tasks_df_wide$time_point),
      task = as.integer(met1_tasks_df_wide$task),
      gr_sex_tp_ta = met1_tasks_df_wide$gr_sex_tp_ta_int,
      task_order = met1_tasks_df_wide$order_tasks,
      id = as.integer(met1_tasks_df_wide$new_id),
      y = met1_tasks_df_wide$simulated_data) #completion time
str(dat_sim_met1_tasks)

met_tasks_sim_model <- sampling(met1_tasks_mod, dat = dat_sim_met1_tasks)
precis(met_tasks_sim_model,depth=2)
precis(met_tasks_sim_model, pars = c("mu_gr_sex_tp_ta","sig_gr_sex_tp_ta","mu_id","sig_id"),depth=2)
saveRDS(met_tasks_sim_model, "met_tasks_sim_model.rds")
met_tasks_sim_model <- readRDS("met_tasks_sim_model.rds")

#check chains
traceplot(met_tasks_sim_model, pars = c('b_group'))
traceplot(met_tasks_sim_model, pars = c('b_sex'))
traceplot(met_tasks_sim_model, pars = c('b_time_point'))
traceplot(met_tasks_sim_model, pars = c('b_task'))
traceplot(met_tasks_sim_model, pars = c("mu_gr_sex_tp_ta","sig_gr_sex_tp_ta","mu_id","sig_id"))

met1_tasks_sim_samples <- as.data.frame(rstan::extract(met_tasks_sim_model))
colnames(met1_tasks_sim_samples)

met_tasks_func(met1_tasks_sim_samples,met1_tasks_df_wide$comp_time)                                                                                                                                                                                                                                                                                                                             
met1_tasks_sim_samples <- samples

colnames(met1_tasks_sim_samples)
