dat_met1_tasks <- list(N = length(met1_tasks_df_wide$new_id),
     N_ids = length(unique(met1_tasks_df_wide$new_id)),
     group = as.integer(met1_tasks_df_wide$group),
     sex = as.integer(met1_tasks_df_wide$sex),
     timepoint = as.integer(met1_tasks_df_wide$time_point),
     task = as.integer(met1_tasks_df_wide$task),
     gr_sex_tp_ta = met1_tasks_df_wide$gr_sex_tp_ta_int,
     task_order = met1_tasks_df_wide$order_tasks,
     id = as.integer(met1_tasks_df_wide$new_id),
     y = met1_tasks_df_wide$comp_time_zscore) #completion time
str(dat_met1_tasks)

met1_tasks_model <- sampling(met1_tasks_mod, dat = dat_met1_tasks,iter=3000)
precis(met1_tasks_model,depth=2)
precis(met1_tasks_model, pars = c("mu_gr_sex_tp_ta","sig_gr_sex_tp_ta","mu_id","sig_id"),depth=2)
saveRDS(met1_tasks_model, "met1_tasks_model.rds")
met1_tasks_model <- readRDS("met1_tasks_model.rds")

#check chains
traceplot(met1_tasks_model, pars = c('b_group'))
traceplot(met1_tasks_model, pars = c('b_sex'))
traceplot(met1_tasks_model, pars = c('b_time_point'))
traceplot(met1_tasks_model, pars = c('b_task'))
traceplot(met1_tasks_model, pars = c("mu_gr_sex_tp_ta","sig_gr_sex_tp_ta","mu_id","sig_id"))

#Looking at LOO
loo_met1_tasks_mod <- loo(met1_tasks_model)
plot(loo_met1_tasks_mod,diagnostic = c("k"),label_points = FALSE,main = "PSIS diagnostic plot")
print(which(loo_met1_tasks_mod$diagnostics$pareto_k > 0.7))

#Extracting samples
met1_tasks_samples <- as.data.frame(rstan::extract(met1_tasks_model))
colnames(met1_tasks_samples)

met_tasks_func(met1_tasks_samples,met1_tasks_df_wide$comp_time)
met1_tasks_samples <- samples

colnames(met1_tasks_samples)
apply(met1_tasks_samples[c(119:160)],2,summary)
rm(samples)

