####MET Stage 2 Tasks####
  ####Loading in MET 2 Tasks models####
met2_tasks_prior_mod <- stan_model("met2_tasks_prior.stan")

met2_tasks_mod <- stan_model("met2_tasks.stan")
  ####MET Stages 2 Tasks Set-Up####
#Putting it all together in a dataframe to use for analyses
colnames(met_perf_all)
met2_tasks_df_wide <- gather(met_perf_all[c(8:10)], key = 'task', value = 'comp_time')
met2_tasks_df_wide$new_id <- rep(met_perf_all$new_id,3)
met2_tasks_df_wide$sex <- rep(met_perf_all$Sex,3)
met2_tasks_df_wide$group <- rep(met_perf_all$group,3)
met2_tasks_df_wide$time_point <- rep(met_perf_all$time_point,3)
met2_tasks_df_wide$task <- match(met2_tasks_df_wide$task, unique(met2_tasks_df_wide$task))
met2_tasks_df_wide$order_tasks <- rep(met_perf_all$met2_order,3)
by(met2_tasks_df_wide$comp_time,met2_tasks_df_wide$time_point,summary)

#Now going to delete any NAs in the data frame
length(which(is.na(met2_tasks_df_wide$comp_time))) 
met2_tasks_df_wide <- met2_tasks_df_wide[complete.cases(met2_tasks_df_wide) == TRUE, ]

#Creating the interaction terms for group, sex, timepoint, task
#CTL Baseline
met2_tasks_df_wide$gr_sex_tp_ta[met2_tasks_df_wide$group == 1 & met2_tasks_df_wide$sex == 2 & 
     met2_tasks_df_wide$time_point == 1 & met2_tasks_df_wide$task == 1] <- "ctl_f_bl_squats"
met2_tasks_df_wide$gr_sex_tp_ta[met2_tasks_df_wide$group == 1 & met2_tasks_df_wide$sex == 1 & 
     met2_tasks_df_wide$time_point == 1 & met2_tasks_df_wide$task == 1] <- "ctl_m_bl_squats"
met2_tasks_df_wide$gr_sex_tp_ta[met2_tasks_df_wide$group == 1 & met2_tasks_df_wide$sex == 2 & 
     met2_tasks_df_wide$time_point == 1 & met2_tasks_df_wide$task == 2] <- "ctl_f_bl_lunges"
met2_tasks_df_wide$gr_sex_tp_ta[met2_tasks_df_wide$group == 1 & met2_tasks_df_wide$sex == 1 & 
     met2_tasks_df_wide$time_point == 1 & met2_tasks_df_wide$task == 2] <- "ctl_m_bl_lunges"
met2_tasks_df_wide$gr_sex_tp_ta[met2_tasks_df_wide$group == 1 & met2_tasks_df_wide$sex == 2 & 
     met2_tasks_df_wide$time_point == 1 & met2_tasks_df_wide$task == 3] <- "ctl_f_bl_gm"
met2_tasks_df_wide$gr_sex_tp_ta[met2_tasks_df_wide$group == 1 & met2_tasks_df_wide$sex == 1 & 
     met2_tasks_df_wide$time_point == 1 & met2_tasks_df_wide$task == 3] <- "ctl_m_bl_gm"

#Concussion, 1WPI - both sexes and tasks 1-3
met2_tasks_df_wide$gr_sex_tp_ta[met2_tasks_df_wide$group == 2 & met2_tasks_df_wide$sex == 2 & 
     met2_tasks_df_wide$time_point == 2 & met2_tasks_df_wide$task == 1] <- "conc_f_1wpi_squats"
met2_tasks_df_wide$gr_sex_tp_ta[met2_tasks_df_wide$group == 2 & met2_tasks_df_wide$sex == 1 & 
     met2_tasks_df_wide$time_point == 2 & met2_tasks_df_wide$task == 1] <- "conc_m_1wpi_squats"
met2_tasks_df_wide$gr_sex_tp_ta[met2_tasks_df_wide$group == 2 & met2_tasks_df_wide$sex == 2 & 
     met2_tasks_df_wide$time_point == 2 & met2_tasks_df_wide$task == 2] <- "conc_f_1wpi_lunges"
met2_tasks_df_wide$gr_sex_tp_ta[met2_tasks_df_wide$group == 2 & met2_tasks_df_wide$sex == 1 & 
     met2_tasks_df_wide$time_point == 2 & met2_tasks_df_wide$task == 2] <- "conc_m_1wpi_lunges"
