  ####Prior Model####
#Prior MET Completion Times
dat_prior_met2_tasks <- list(N = length(met2_tasks_df_wide$new_id),
                             N_ids = length(unique(met2_tasks_df_wide$new_id)),
                             group = as.integer(met2_tasks_df_wide$group),
                             sex = as.integer(met2_tasks_df_wide$sex),
                             timepoint = as.integer(met2_tasks_df_wide$time_point),
                             task = as.integer(met2_tasks_df_wide$task),
                             gr_sex_tp_ta = met2_tasks_df_wide$gr_sex_tp_ta_int,
                             task_order = met2_tasks_df_wide$order_tasks,
                             id = as.integer(met2_tasks_df_wide$new_id),
                             y = (met2_tasks_df_wide$comp_time_zscore)*0) #completion time
str(dat_prior_met2_tasks)
#Run the model
met2_tasks_prior_model <- sampling(met2_tasks_prior_mod, dat = dat_prior_met2_tasks)
precis(met2_tasks_prior_model,depth=2)
precis(met2_tasks_prior_model, pars = c("mu_gr_sex_tp_ta","sig_gr_sex_tp_ta","mu_id","sig_id"),depth=2)

saveRDS(met2_tasks_prior_model, "met2_tasks_prior_model.rds")
met2_tasks_prior_model <- readRDS("met2_tasks_prior_model.rds")

#check chains
traceplot(met2_tasks_prior_model, pars = c('b_group'))
traceplot(met2_tasks_prior_model, pars = c('b_sex'))
traceplot(met2_tasks_prior_model, pars = c('b_time_point'))
traceplot(met2_tasks_prior_model, pars = c('b_task'))
traceplot(met2_tasks_prior_model, pars = c("mu_gr_sex_tp_ta","sig_gr_sex_tp_ta","mu_id","sig_id"))

met2_tasks_prior_samples <- as.data.frame(rstan::extract(met2_tasks_prior_model))
colnames(met2_tasks_prior_samples)
#Running through prior function
met2_tasks_func(met2_tasks_prior_samples,met2_tasks_df_wide$comp_time)

met2_tasks_pri_samples <- samples
colnames(met2_tasks_pri_samples)
rm(samples)

