dat_met2_tasks <- list(N = length(met2_tasks_df_wide$new_id),
                       N_ids = length(unique(met2_tasks_df_wide$new_id)),
                       group = as.integer(met2_tasks_df_wide$group),
                       sex = as.integer(met2_tasks_df_wide$sex),
                       timepoint = as.integer(met2_tasks_df_wide$time_point),
                       task = as.integer(met2_tasks_df_wide$task),
                       gr_sex_tp_ta = met2_tasks_df_wide$gr_sex_tp_ta_int,
                       task_order = met2_tasks_df_wide$order_tasks,
                       id = as.integer(met2_tasks_df_wide$new_id),
                       y = met2_tasks_df_wide$comp_time_zscore) #completion time
str(dat_met2_tasks)
met2_tasks_model <- sampling(met2_tasks_mod, dat = dat_met2_tasks)
precis(met2_tasks_model,depth=2)
precis(met2_tasks_model, pars = c("mu_gr_sex_tp_ta","sig_gr_sex_tp_ta","mu_id","sig_id"),depth=2)
saveRDS(met2_tasks_model, "met2_tasks_model.rds")
met2_tasks_model <- readRDS("met2_tasks_model.rds")

#check chains
traceplot(met2_tasks_model, pars = c('b_group'))
traceplot(met2_tasks_model, pars = c('b_sex'))
traceplot(met2_tasks_model, pars = c('b_time_point'))
traceplot(met2_tasks_model, pars = c('b_task'))

#Looking at LOO
loo_met2_tasks_mod <- loo(met2_tasks_model)
plot(loo_met2_tasks_mod,diagnostic = c("k"),label_points = FALSE,main = "PSIS diagnostic plot")
print(which(loo_met2_tasks_mod$diagnostics$pareto_k > 0.7))

#Extracting samples
met2_tasks_samples <- as.data.frame(rstan::extract(met2_tasks_model))
colnames(met2_tasks_samples)

met2_tasks_func(met2_tasks_samples,met2_tasks_df_wide$comp_time)
