set.seed(264)
met2_tasks_samples_real <- as.data.frame(rstan::extract(met2_tasks_model))
colnames(met2_tasks_samples_real)
ppc_met2_tasks_stu_t_func(met2_tasks_samples_real,met2_tasks_df_wide$comp_time)

pred_ppc_met2_samples <- pred_df

colnames(pred_ppc_met2_samples)
plot_met2_tasks_ppc_bl <- rbind.data.frame(gather(pred_ppc_met2_samples[c(43:48)]))
plot_met2_tasks_ppc_bl$task <- c(rep("Squats",2000),rep("Lunges",2000),rep("Hip Hinges",2000))
plot_met2_tasks_ppc_bl$group <- c(rep(c(rep("CTL Female",1000),rep("CTL Male",1000)),3))

fig_met2_tasks_ppc_bl <- plot_met2_tasks_ppc_bl %>%
  ggplot(aes(y = task,x = value,fill = group)) + 
  theme_classic()+
  theme(strip.text.x = element_text(face = 'bold',size = 10),
        axis.title.x = element_text(size = 9,face = 'bold'),
        axis.title.y = element_blank(),
        axis.text.y = element_text(face = 'bold',size = 9),
        legend.text = element_text(size = 8),
        legend.title = element_blank(),
        legend.position = c(0.90,.1),
        legend.spacing.y = unit(0, "pt"),
        legend.spacing.x = unit(0, "pt"),
        legend.box.margin=margin(-0.2,-0.2,-0.2,-0.2),
        axis.text.x = element_text(face = 'bold',size = 8))+
  scale_fill_manual("Group",values = c("violetred1","royalblue1")) +xlim(0,30)+
  stat_halfeye(.width = c(0.70,0.90),alpha = 0.7) +
  xlab("Completion time (seconds)") + ggtitle("MET Stage 2 Tasks - PPC (Bl)")
fig_met2_tasks_ppc_bl

