  ####Prior and Posterior Graphs + Raw Median####
colnames(met2_tasks_samples)
colnames(met2_tasks_pri_samples)
by(met2_tasks_df_wide$comp_time,met2_tasks_df_wide$gr_sex_tp_ta,mean)
plot_met2_tasks_bl_pr_post <- rbind.data.frame(gather(met2_tasks_samples[c(119:124)]),
                                               gather(met2_tasks_pri_samples[c(119:124)]))
plot_met2_tasks_bl_pr_post$task <- c(rep("Squats",8000),rep("Reverse Lunges",8000),
                                     rep("Hip Hinges",8000),rep("Squats",8000),
                                     rep("Reverse Lunges",8000),rep("Hip Hinges",8000))
plot_met2_tasks_bl_pr_post$group <- c(rep(c(rep("Female",4000),rep("Male",4000)),3),
                                      rep(c(rep("Prior Female",4000),rep("Prior Male",4000)),3))
fig_met2_tasks_bl_pr_post <- plot_met2_tasks_bl_pr_post %>%
  ggplot(aes(y = task,x = value,fill = group)) + 
  theme_classic()+
  theme(strip.text.x = element_text(face = 'bold',size = 10),
        axis.title.x = element_text(size = 9,face = 'bold'),
        axis.title.y = element_blank(),
        axis.text.y = element_text(face = 'bold',size = 7),
        legend.text = element_text(size = 8),
        legend.title = element_blank(),
        legend.position = c(0.9,.15),
        legend.spacing.y = unit(0, "pt"),
        legend.spacing.x = unit(0, "pt"),
        legend.box.margin=margin(-0.2,-0.2,-0.2,-0.2),
        axis.text.x = element_text(face = 'bold',size = 8))+
  scale_fill_manual("Group",values = c("maroon3","royalblue3","grey65","grey85")) +xlim(5,20)+
  stat_halfeye(.width = c(0.70,0.90),alpha = 0.7) +
  geom_segment(aes(x = 14.1, xend = 14.1, y = "Hip Hinges", yend = "Reverse Lunges"),color = "maroon1") +
  geom_segment(aes(x = 13.0, xend = 13.0, y = "Hip Hinges", yend = "Reverse Lunges"),color = "royalblue2") +
  geom_segment(aes(x = 14.4, xend = 14.4, y = "Reverse Lunges", yend = "Squats"),color = "maroon1") +
  geom_segment(aes(x = 13.3, xend = 13.3, y = "Reverse Lunges", yend = "Squats"),color = "royalblue2") +
  geom_segment(aes(x = 12.5, xend = 12.5, y = "Squats", yend = 4),color = "maroon1") +
  geom_segment(aes(x = 11.2, xend = 11.2, y = "Squats", yend = 4),color = "royalblue2") +
  xlab("Completion Times (seconds)") + ggtitle("MET2 Tasks Baseline (Priors + Posteriors)")
fig_met2_tasks_bl_pr_post

