  ####Prior Model####
#Prior MET 3 Completion Times
dat_prior_met3_tasks <- list(N = length(met3_tasks_df_wide$new_id),
                             N_ids = length(unique(met3_tasks_df_wide$new_id)),
                             group = as.integer(met3_tasks_df_wide$group),
                             sex = as.integer(met3_tasks_df_wide$sex),
                             timepoint = as.integer(met3_tasks_df_wide$time_point),
                             task = as.integer(met3_tasks_df_wide$task),
                             gr_sex_tp_ta = met3_tasks_df_wide$gr_sex_tp_ta_int,
                             task_order = met3_tasks_df_wide$order_tasks,
                             id = as.integer(met3_tasks_df_wide$new_id),
                             y = (met3_tasks_df_wide$comp_time_zscore)*0) #completion time
str(dat_prior_met3_tasks)
met3_tasks_prior_model <- sampling(met3_tasks_prior_mod, dat = dat_prior_met3_tasks)
precis(met3_tasks_prior_model,depth=2)
precis(met3_tasks_prior_model, pars = c("mu_gr_sex_tp_ta","sig_gr_sex_tp_ta","mu_id","sig_id"),depth=2)
saveRDS(met3_tasks_prior_model, "met3_tasks_prior_model.rds")
met3_tasks_prior_model <- readRDS("met3_tasks_prior_model.rds")

#check chains
traceplot(met3_tasks_prior_model, pars = c('b_group'))
traceplot(met3_tasks_prior_model, pars = c('b_sex'))
traceplot(met3_tasks_prior_model, pars = c('b_time_point'))
traceplot(met3_tasks_prior_model, pars = c('b_task'))
traceplot(met3_tasks_prior_model, pars = c("mu_gr_sex_tp_ta","sig_gr_sex_tp_ta","mu_id","sig_id"))

met3_tasks_prior_samples <- as.data.frame(rstan::extract(met3_tasks_prior_model))
colnames(met3_tasks_prior_samples)
#Running through prior function
met3_tasks_func(met3_tasks_prior_samples,met3_tasks_df_wide$comp_time)
