  stat_halfeye(.width = c(0.70,0.90),alpha = 0.7) +
  geom_segment(aes(x = 39.2, xend = 39.2, y = "Hip Hinges", yend = "Reverse Lunges"),color = "maroon1") +
  geom_segment(aes(x = 35.7, xend = 35.7, y = "Hip Hinges", yend = "Reverse Lunges"),color = "royalblue2") +
  geom_segment(aes(x = 40.3, xend = 40.3, y = "Reverse Lunges", yend = "Squats"),color = "maroon1") +
  geom_segment(aes(x = 37.0, xend = 37.0, y = "Reverse Lunges", yend = "Squats"),color = "royalblue2") +
  geom_segment(aes(x = 36.6, xend = 36.6, y = "Squats", yend = 4),color = "maroon1") +
  geom_segment(aes(x = 33.0, xend = 33.0, y = "Squats", yend = 4),color = "royalblue2") +
