dat_prior_met3_cowat_sq <- list(N = length(met3_sq_cowat_df_wide$new_id),
                           N_ids = length(unique(met3_sq_cowat_df_wide$new_id)),
                           group = as.integer(met3_sq_cowat_df_wide$group),
                           sex = as.integer(met3_sq_cowat_df_wide$sex),
                           timepoint = as.integer(met3_sq_cowat_df_wide$time_point),
                           gr_sex_tp = met3_sq_cowat_df_wide$gr_sex_tp_int,
                           id = as.integer(met3_sq_cowat_df_wide$new_id),
                           outcome = (met3_sq_cowat_df_wide$cowat_sq)*0)
str(dat_prior_met3_cowat_sq)

