  ####COWAT Lunges Functions####
met_cowat_lu_func <- function(samples) {
  samples <- samples[c(1:11,337:350,181:183,26:27)]
  colnames(samples) <- c("ctl","conc","male","female","bl","onewpi","twowpi",
                         "threewpi","fourwpi","sixwpi","eightwpi","ctl_f_bl.int",
                         "ctl_m_bl.int","conc_f_1wpi.int","conc_m_1wpi.int","conc_f_2wpi.int",
                         "conc_m_2wpi.int","conc_f_3wpi.int","conc_m_3wpi.int","conc_f_4wpi.int",
                         "conc_m_4wpi.int","conc_f_6wpi.int","conc_m_6wpi.int","conc_f_8wpi.int",
                         "conc_m_8wpi.int","mu_id","sig_id","phi","mu_gr_sex_tp","sig_gr_sex_tp")
  samples$ctl_f_bl <- samples$ctl+samples$female+samples$bl+samples$ctl_f_bl.int
  samples$ctl_m_bl <- samples$ctl+samples$male+samples$bl+samples$ctl_m_bl.int
  
  samples$conc_f_1wpi <- samples$conc+samples$female+samples$onewpi+samples$conc_f_1wpi.int
  samples$conc_m_1wpi <- samples$conc+samples$male+samples$onewpi+samples$conc_m_1wpi.int
  
  samples$conc_f_2wpi <- samples$conc+samples$female+samples$twowpi+samples$conc_f_2wpi.int
  samples$conc_m_2wpi <- samples$conc+samples$male+samples$twowpi+samples$conc_m_2wpi.int
  
  samples$conc_f_3wpi <- samples$conc+samples$female+samples$threewpi+samples$conc_f_3wpi.int
  samples$conc_m_3wpi <- samples$conc+samples$male+samples$threewpi+samples$conc_m_3wpi.int
  
  samples$conc_f_4wpi <- samples$conc+samples$female+samples$fourwpi+samples$conc_f_4wpi.int
  samples$conc_m_4wpi <- samples$conc+samples$male+samples$fourwpi+samples$conc_m_4wpi.int
  
  samples$conc_f_6wpi <- samples$conc+samples$female+samples$sixwpi+samples$conc_f_6wpi.int
  samples$conc_m_6wpi <- samples$conc+samples$male+samples$sixwpi+samples$conc_m_6wpi.int
  
  samples$conc_f_8wpi <- samples$conc+samples$female+samples$eightwpi+samples$conc_f_8wpi.int
  samples$conc_m_8wpi <- samples$conc+samples$male+samples$eightwpi+samples$conc_m_8wpi.int
  
  samples[c(45:69)] <- apply(samples[c(1:11,31:44)],2,exp)
  colnames(samples) <- c(paste(colnames(samples[c(1:25)]),"log",sep="_"),colnames(samples[c(26:30)]),
                         paste(colnames(samples[c(31:44)]),"log",sep="_"),colnames(samples[c(1:11,31:44)]))
  assign("samples",samples,envir = .GlobalEnv)
}

ppc_met3_lu_cowat_neg_binom_func <- function(samples) {
  extracted_samples <- samples[c(1:11,337:350,181:183,26:27)]
  colnames(extracted_samples) <- c("ctl","conc","male","female","bl","onewpi","twowpi",
                                   "threewpi","fourwpi","sixwpi","eightwpi","ctl_f_bl.int",
                                   "ctl_m_bl.int","conc_f_1wpi.int","conc_m_1wpi.int","conc_f_2wpi.int",
                                   "conc_m_2wpi.int","conc_f_3wpi.int","conc_m_3wpi.int","conc_f_4wpi.int",
                                   "conc_m_4wpi.int","conc_f_6wpi.int","conc_m_6wpi.int","conc_f_8wpi.int",
                                   "conc_m_8wpi.int","mu_id","sig_id","phi","mu_gr_sex_tp",
                                   "sig_gr_sex_tp")
  
  #Creating the b_id parameter
  extracted_samples$b_id <- NA
  for (i in 1:length(extracted_samples$b_id)) {
    extracted_samples$b_id[i] <- rnorm(1,mean=extracted_samples$mu_id[i],sd=extracted_samples$sig_id[i])
  }
  
  pred_df <- as.data.frame(matrix(NA,nrow=1000,ncol=14))
  colnames(pred_df) <- c("ctl_f_bl","ctl_m_bl","conc_f_1wpi","conc_m_1wpi","conc_f_2wpi",
                         "conc_m_2wpi","conc_f_3wpi","conc_m_3wpi","conc_f_4wpi",
                         "conc_m_4wpi","conc_f_6wpi","conc_m_6wpi","conc_f_8wpi","conc_m_8wpi")
  
  sample_num <- sample(1:4000,1000,replace=FALSE)
  for (i in 1:length(sample_num)) {
    extracted_row <- extracted_samples[sample_num[i],]
    
    pred_df$ctl_f_bl[i] <- rnbinom(1,size=extracted_row$phi,mu=exp(extracted_row$ctl+extracted_row$female+extracted_row$bl+extracted_row$ctl_f_bl.int+extracted_row$b_id))
    pred_df$ctl_m_bl[i] <- rnbinom(1,size=extracted_row$phi,mu=exp(extracted_row$ctl+extracted_row$male+extracted_row$bl+extracted_row$ctl_m_bl.int+extracted_row$b_id))
    
    pred_df$conc_f_1wpi[i] <- rnbinom(1,size=extracted_row$phi,mu=exp(extracted_row$conc+extracted_row$female+extracted_row$onewpi+extracted_row$conc_f_1wpi.int+extracted_row$b_id))
    pred_df$conc_m_1wpi[i] <- rnbinom(1,size=extracted_row$phi,mu=exp(extracted_row$conc+extracted_row$male+extracted_row$onewpi+extracted_row$conc_m_1wpi.int+extracted_row$b_id))
    
    pred_df$conc_f_2wpi[i] <- rnbinom(1,size=extracted_row$phi,mu=exp(extracted_row$conc+extracted_row$female+extracted_row$twowpi+extracted_row$conc_f_2wpi.int+extracted_row$b_id))
    pred_df$conc_m_2wpi[i] <- rnbinom(1,size=extracted_row$phi,mu=exp(extracted_row$conc+extracted_row$male+extracted_row$twowpi+extracted_row$conc_m_2wpi.int+extracted_row$b_id))
    
    pred_df$conc_f_3wpi[i] <- rnbinom(1,size=extracted_row$phi,mu=exp(extracted_row$conc+extracted_row$female+extracted_row$threewpi+extracted_row$conc_f_3wpi.int+extracted_row$b_id))
    pred_df$conc_m_3wpi[i] <- rnbinom(1,size=extracted_row$phi,mu=exp(extracted_row$conc+extracted_row$male+extracted_row$threewpi+extracted_row$conc_m_3wpi.int+extracted_row$b_id))
    
    pred_df$conc_f_4wpi[i] <- rnbinom(1,size=extracted_row$phi,mu=exp(extracted_row$conc+extracted_row$female+extracted_row$fourwpi+extracted_row$conc_f_4wpi.int+extracted_row$b_id))
    pred_df$conc_m_4wpi[i] <- rnbinom(1,size=extracted_row$phi,mu=exp(extracted_row$conc+extracted_row$male+extracted_row$fourwpi+extracted_row$conc_m_4wpi.int+extracted_row$b_id))
    
    pred_df$conc_f_6wpi[i] <- rnbinom(1,size=extracted_row$phi,mu=exp(extracted_row$conc+extracted_row$female+extracted_row$sixwpi+extracted_row$conc_f_6wpi.int+extracted_row$b_id))
    pred_df$conc_m_6wpi[i] <- rnbinom(1,size=extracted_row$phi,mu=exp(extracted_row$conc+extracted_row$male+extracted_row$sixwpi+extracted_row$conc_m_6wpi.int+extracted_row$b_id))
    
    pred_df$conc_f_8wpi[i] <- rnbinom(1,size=extracted_row$phi,mu=exp(extracted_row$conc+extracted_row$female+extracted_row$eightwpi+extracted_row$conc_f_8wpi.int+extracted_row$b_id))
    pred_df$conc_m_8wpi[i] <- rnbinom(1,size=extracted_row$phi,mu=exp(extracted_row$conc+extracted_row$male+extracted_row$eightwpi+extracted_row$conc_m_8wpi.int+extracted_row$b_id))
  }
  assign("pred_df",pred_df,envir = .GlobalEnv)
}

  ####Prior Model for COWAT Lunges####
dat_prior_met3_cowat_lu <- list(N = length(met3_lu_cowat_df_wide$new_id),
                                N_ids = length(unique(met3_lu_cowat_df_wide$new_id)),
                                group = as.integer(met3_lu_cowat_df_wide$group),
                                sex = as.integer(met3_lu_cowat_df_wide$sex),
                                timepoint = as.integer(met3_lu_cowat_df_wide$time_point),
                                gr_sex_tp = met3_lu_cowat_df_wide$gr_sex_tp_int,
                                id = as.integer(met3_lu_cowat_df_wide$new_id),
                                outcome = (met3_lu_cowat_df_wide$cowat_lu)*0)
str(dat_prior_met3_cowat_lu)

met3_lu_cowat_prior_model <- sampling(met3_cowat_prior_mod, dat = dat_prior_met3_cowat_lu)
precis(met3_lu_cowat_prior_model,depth=2)
precis(met3_lu_cowat_prior_model,pars = c("mu_gr_sex_tp","sig_gr_sex_tp","mu_id","sig_id"),depth=2)
saveRDS(met3_lu_cowat_prior_model, "met3_lu_cowat_prior_model.rds")
met3_lu_cowat_prior_model <- readRDS("met3_lu_cowat_prior_model.rds")

#check chains
traceplot(met3_lu_cowat_prior_model, pars = c('b_group'))
traceplot(met3_lu_cowat_prior_model, pars = c('b_sex'))
traceplot(met3_lu_cowat_prior_model, pars = c('b_time_point'))
traceplot(met3_lu_cowat_prior_model, pars = c("mu_gr_sex_tp","sig_gr_sex_tp","mu_id","sig_id"))

met3_lu_cowat_prior_samples <- as.data.frame(rstan::extract(met3_lu_cowat_prior_model))
colnames(met3_lu_cowat_prior_samples)

met_cowat_lu_func(met3_lu_cowat_prior_samples)
met3_lu_cowat_pri_samples <- samples
rm(samples)
apply(met3_lu_cowat_pri_samples[c(45:69)],2,summary)

