dat_sim_met3_lu_cowat <- list(N = length(met3_lu_cowat_df_wide$new_id),
                              N_ids = length(unique(met3_lu_cowat_df_wide$new_id)),
                              group = as.integer(met3_lu_cowat_df_wide$group),
                              sex = as.integer(met3_lu_cowat_df_wide$sex),
                              timepoint = as.integer(met3_lu_cowat_df_wide$time_point),
                              gr_sex_tp = met3_lu_cowat_df_wide$gr_sex_tp_int,
                              id = as.integer(met3_lu_cowat_df_wide$new_id),
                              outcome = (met3_lu_cowat_df_wide$simulated_data))
str(dat_sim_met3_lu_cowat)

met3_lu_cowat_sim_model <- sampling(met3_cowat_mod, dat = dat_sim_met3_lu_cowat)
precis(met3_lu_cowat_sim_model,depth=2)
precis(met3_lu_cowat_sim_model,depth=2,pars=c("mu_gr_sex_tp","sig_gr_sex_tp","mu_id","sig_id"))
saveRDS(met3_lu_cowat_sim_model, "met3_lu_cowat_sim_model.rds")
met3_lu_cowat_sim_model <- readRDS("met3_lu_cowat_sim_model.rds")

#check chains
traceplot(met3_lu_cowat_sim_model, pars = c('b_group'))
traceplot(met3_lu_cowat_sim_model, pars = c('b_sex'))
traceplot(met3_lu_cowat_sim_model, pars = c('b_time_point'))
traceplot(met3_lu_cowat_sim_model, pars = c("mu_gr_sex_tp","sig_gr_sex_tp","mu_id","sig_id"))

met3_lu_cowat_sim_samples <- as.data.frame(rstan::extract(met3_lu_cowat_sim_model))
colnames(met3_lu_cowat_sim_samples)

met_cowat_lu_func(met3_lu_cowat_sim_samples)                                                                                                                                                                                                                                                                                                                             
met3_lu_cowat_sim_samples <- samples
rm(samples)
colnames(met3_lu_cowat_sim_samples)
apply(met3_lu_cowat_sim_samples[c(45:69)],2,summary)

