  #####MET3 Squat COWAT Posterior Model#####
dat_met3_lu_cowat <- list(N = length(met3_lu_cowat_df_wide$new_id),
                          N_ids = length(unique(met3_lu_cowat_df_wide$new_id)),
                          group = as.integer(met3_lu_cowat_df_wide$group),
                          sex = as.integer(met3_lu_cowat_df_wide$sex),
                          timepoint = as.integer(met3_lu_cowat_df_wide$time_point),
                          gr_sex_tp = met3_lu_cowat_df_wide$gr_sex_tp_int,
                          id = as.integer(met3_lu_cowat_df_wide$new_id),
                          outcome = (met3_lu_cowat_df_wide$cowat_lu))
str(dat_met3_lu_cowat)

#Running model now
met3_lu_cowat_model <- sampling(met3_cowat_mod, dat = dat_met3_lu_cowat)
precis(met3_lu_cowat_model,depth=2)
precis(met3_lu_cowat_model,depth=2,pars=c("mu_gr_sex_tp","sig_gr_sex_tp","mu_id","sig_id"))
saveRDS(met3_lu_cowat_model, "met3_lu_cowat_model.rds")
met3_lu_cowat_model <- readRDS("met3_lu_cowat_model.rds")

#Looking at LOO
loo_met3_lu_cowat_mod <- loo(met3_lu_cowat_model)
plot(loo_met3_lu_cowat_mod,diagnostic = c("k"),label_points = FALSE,main = "PSIS diagnostic plot")
print(which(loo_met3_lu_cowat_mod$diagnostics$pareto_k > 0.7))

#check chains
traceplot(met3_lu_cowat_model, pars = c('b_group'))
traceplot(met3_lu_cowat_model, pars = c('b_sex'))
traceplot(met3_lu_cowat_model, pars = c('b_time_point'))
traceplot(met3_lu_cowat_model, pars = c("mu_gr_sex_tp","sig_gr_sex_tp","mu_id","sig_id"))

#Extracting samples
met3_lu_cowat_samples <- as.data.frame(rstan::extract(met3_lu_cowat_model))
colnames(met3_lu_cowat_samples)

met_cowat_lu_func(met3_lu_cowat_samples)
met3_lu_cowat_samples <- samples
colnames(met3_lu_cowat_samples)
apply(met3_lu_cowat_samples[c(56:69)],2,summary)

write.csv(met3_lu_cowat_samples,"met3_lu_cowat_samples.csv")
rm(samples)

