dat_sim_met4_sdlj <- list(N = length(met4_sdlj_df_wide$new_id),
  N_ids = length(unique(met4_sdlj_df_wide$new_id)),
  group = as.integer(met4_sdlj_df_wide$group),
  sex = as.integer(met4_sdlj_df_wide$sex),
  timepoint = as.integer(met4_sdlj_df_wide$time_point),
  gr_sex_tp = met4_sdlj_df_wide$gr_sex_tp_int,
  id = as.integer(met4_sdlj_df_wide$new_id),
  outcome = (met4_sdlj_df_wide$simulated_data),
  M = 12)
str(dat_sim_met4_sdlj)

met4_sdlj_sim_model <- sampling(met4_sdlj_mod, dat = dat_sim_met4_sdlj)
precis(met4_sdlj_sim_model,depth=2)
saveRDS(met4_sdlj_sim_model, "met4_sdlj_sim_model.rds")
met4_sdlj_sim_model <- readRDS("met4_sdlj_sim_model.rds")

#check chains
traceplot(met4_sdlj_sim_model, pars = c('b_group'))
traceplot(met4_sdlj_sim_model, pars = c('b_sex'))
traceplot(met4_sdlj_sim_model, pars = c('b_time_point'))

met4_sdlj_sim_samples <- as.data.frame(rstan::extract(met4_sdlj_sim_model))
colnames(met4_sdlj_sim_samples)

met4_sdlj_func(met4_sdlj_sim_samples)                                                                                                                                                                                                                                                                                                                             
met4_sdlj_sim_samples <- samples
rm(samples)
colnames(met4_sdlj_sim_samples)
apply(met4_sdlj_sim_samples[c(42:66)],2,summary)

