  ####Posterior Model####
dat_met4_sdlj <- list(N = length(met4_sdlj_df_wide$new_id),
    N_ids = length(unique(met4_sdlj_df_wide$new_id)),
    group = as.integer(met4_sdlj_df_wide$group),
    sex = as.integer(met4_sdlj_df_wide$sex),
    timepoint = as.integer(met4_sdlj_df_wide$time_point),
    gr_sex_tp = met4_sdlj_df_wide$gr_sex_tp_int,
    id = as.integer(met4_sdlj_df_wide$new_id),
    outcome = (met4_sdlj_df_wide$sdlj),
    M = 12)
str(dat_met4_sdlj)

#Running model now
met4_sdlj_model <- sampling(met4_sdlj_mod, dat = dat_met4_sdlj)
precis(met4_sdlj_model,depth=2)
saveRDS(met4_sdlj_model, "met4_sdlj_model.rds")
met4_sdlj_model <- readRDS("met4_sdlj_model.rds")

#Looking at LOO
loo_sdlj_mod <- loo(met4_sdlj_model)
plot(loo_sdlj_mod,diagnostic = c("k"),label_points = FALSE,main = "PSIS diagnostic plot")
print(which(loo_sdlj_mod$diagnostics$pareto_k > 0.7))
met4_sdlj_df_wide$sdlj[which(loo_sdlj_mod$diagnostics$pareto_k > 0.7)]
table(met4_sdlj_df_wide$sdlj)

#check chains
traceplot(met4_sdlj_model, pars = c('b_group'))
traceplot(met4_sdlj_model, pars = c('b_sex'))
traceplot(met4_sdlj_model, pars = c('b_time_point'))

#Extracting samples
met4_sdlj_samples <- as.data.frame(rstan::extract(met4_sdlj_model))
met4_sdlj_prob_samples <- as.data.frame(rstan::extract(met4_sdlj_model)$pi)
summary(met4_sdlj_prob_samples)

met4_sdlj_func(met4_sdlj_samples)
met4_sdlj_samples <- samples
colnames(met4_sdlj_samples)
apply(met4_sdlj_samples[c(42:66)],2,summary)
rm(samples)

