dat_prior_met4_jo1 <- list(N = length(met4_jo1_df_wide$new_id),
                            N_ids = length(unique(met4_jo1_df_wide$new_id)),
                            group = as.integer(met4_jo1_df_wide$group),
                            sex = as.integer(met4_jo1_df_wide$sex),
                            timepoint = as.integer(met4_jo1_df_wide$time_point),
                            gr_sex_tp = met4_jo1_df_wide$gr_sex_tp_int,
                            id = as.integer(met4_jo1_df_wide$new_id),
                            outcome = (met4_jo1_df_wide$jo1)*0)
str(dat_prior_met4_jo1)

met4_jo1_prior_model <- sampling(met4_jo1_prior_mod, dat = dat_prior_met4_jo1)
precis(met4_jo1_prior_model,depth=2)
saveRDS(met4_jo1_prior_model, "met4_jo1_prior_model.rds")
