dat_sim_met4_jo2 <- list(N = length(met4_jo2_df_wide$new_id),
                         N_ids = length(unique(met4_jo2_df_wide$new_id)),
                         group = as.integer(met4_jo2_df_wide$group),
                         sex = as.integer(met4_jo2_df_wide$sex),
                         timepoint = as.integer(met4_jo2_df_wide$time_point),
                         gr_sex_tp = met4_jo2_df_wide$gr_sex_tp_int,
                         id = as.integer(met4_jo2_df_wide$new_id),
                         outcome = (met4_jo2_df_wide$simulated_data))
str(dat_sim_met4_jo2)
met4_jo2_sim_model <- sampling(met4_jo2_mod, dat = dat_sim_met4_jo2)
precis(met4_jo2_sim_model,depth=2)
saveRDS(met4_jo2_sim_model, "met4_jo2_sim_model.rds")
met4_jo2_sim_model <- readRDS("met4_jo2_sim_model.rds")

#check chains
traceplot(met4_jo2_sim_model, pars = c('b_group'))
traceplot(met4_jo2_sim_model, pars = c('b_sex'))
traceplot(met4_jo2_sim_model, pars = c('b_time_point'))

met4_jo2_sim_samples <- as.data.frame(rstan::extract(met4_jo2_sim_model))
colnames(met4_jo2_sim_samples)

met4_jo2_func(met4_jo2_sim_samples)                                                                                                                                                                                                                                                                                                                             
met4_jo2_sim_samples <- samples
rm(samples)
colnames(met4_jo2_sim_samples)
apply(met4_jo2_sim_samples[c(43:67)],2,summary)

