  ####Real Data for JO2####
dat_met4_jo2 <- list(N = length(met4_jo2_df_wide$new_id),
                     N_ids = length(unique(met4_jo2_df_wide$new_id)),
                     group = as.integer(met4_jo2_df_wide$group),
                     sex = as.integer(met4_jo2_df_wide$sex),
                     timepoint = as.integer(met4_jo2_df_wide$time_point),
                     gr_sex_tp = met4_jo2_df_wide$gr_sex_tp_int,
                     id = as.integer(met4_jo2_df_wide$new_id),
                     outcome = (met4_jo2_df_wide$jo2))
str(dat_met4_jo2)

#Running model now
met4_jo2_model <- sampling(met4_jo2_mod, dat = dat_met4_jo2)
precis(met4_jo2_model,depth=2)
saveRDS(met4_jo2_model, "met4_jo2_model.rds")
met4_jo2_model <- readRDS("met4_jo2_model.rds")

#Looking at LOO
loo_jo2_mod <- loo(met4_jo2_model)
plot(loo_jo2_mod,diagnostic = c("k"),label_points = FALSE,main = "PSIS diagnostic plot")
print(which(loo_jo2_mod$diagnostics$pareto_k > 0.7))

#check chains
traceplot(met4_jo2_model, pars = c('b_group'))
traceplot(met4_jo2_model, pars = c('b_sex'))
traceplot(met4_jo2_model, pars = c('b_time_point'))

#Extracting samples
met4_jo2_samples <- as.data.frame(rstan::extract(met4_jo2_model))
colnames(met4_jo2_samples)

met4_jo2_func(met4_jo2_samples)
met4_jo2_samples <- samples
colnames(met4_jo2_samples)
apply(met4_jo2_samples[c(54:67)],2,summary)
rm(samples)

