####HVLT####
  ####Loading in models####
met_hvlt_prior_mod <- stan_model("met_hvlt_prior.stan")

met_hvlt_mod <- stan_model("met_hvlt.stan")
  ####HVLT Set-Up####
colnames(met_perf_all)
met_hvlt_df_wide <- gather(met_perf_all[c(24)], key = 'task', value = 'hvlt')
met_hvlt_df_wide$new_id <- met_perf_all$new_id
met_hvlt_df_wide$sex <- met_perf_all$Sex
met_hvlt_df_wide$group <- met_perf_all$group
met_hvlt_df_wide$time_point <- met_perf_all$time_point
met_hvlt_df_wide$task <- match(met_hvlt_df_wide$task, unique(met_hvlt_df_wide$task))

by(met_hvlt_df_wide$hvlt,met_hvlt_df_wide$group,summary)
by(met_hvlt_df_wide$hvlt,met_hvlt_df_wide$sex,summary)
by(met_hvlt_df_wide$hvlt,met_hvlt_df_wide$time_point,summary)

#Now going to delete any NAs in the data frame
length(which(is.na(met_hvlt_df_wide$hvlt)))
met_hvlt_df_wide <- met_hvlt_df_wide[complete.cases(met_hvlt_df_wide) == TRUE, ] 
unique(met_hvlt_df_wide$task)
unique(met_hvlt_df_wide$sex)
unique(met_hvlt_df_wide$group)
unique(met_hvlt_df_wide$time_point)

#Creating the interaction terms for group, sex, timepoint, task
#CTL Baseline
met_hvlt_df_wide$gr_sex_tp[met_hvlt_df_wide$group == 1 & met_hvlt_df_wide$sex == 2 & 
    met_hvlt_df_wide$time_point == 1] <- "ctl_f_bl"
met_hvlt_df_wide$gr_sex_tp[met_hvlt_df_wide$group == 1 & met_hvlt_df_wide$sex == 1 & 
    met_hvlt_df_wide$time_point == 1] <- "ctl_m_bl"

#Concussion, 1WPI - both sexes and tasks 1-3
met_hvlt_df_wide$gr_sex_tp[met_hvlt_df_wide$group == 2 & met_hvlt_df_wide$sex == 2 & 
    met_hvlt_df_wide$time_point == 2] <- "conc_f_1wpi"
met_hvlt_df_wide$gr_sex_tp[met_hvlt_df_wide$group == 2 & met_hvlt_df_wide$sex == 1 & 
    met_hvlt_df_wide$time_point == 2] <- "conc_m_1wpi"

#Concussion, 2WPI - both sexes and tasks 1-3
met_hvlt_df_wide$gr_sex_tp[met_hvlt_df_wide$group == 2 & met_hvlt_df_wide$sex == 2 & 
    met_hvlt_df_wide$time_point == 3] <- "conc_f_2wpi"
met_hvlt_df_wide$gr_sex_tp[met_hvlt_df_wide$group == 2 & met_hvlt_df_wide$sex == 1 & 
    met_hvlt_df_wide$time_point == 3] <- "conc_m_2wpi"

#Concussion, 3WPI - both sexes and tasks 1-3
met_hvlt_df_wide$gr_sex_tp[met_hvlt_df_wide$group == 2 & met_hvlt_df_wide$sex == 2 & 
     met_hvlt_df_wide$time_point == 4] <- "conc_f_3wpi"
met_hvlt_df_wide$gr_sex_tp[met_hvlt_df_wide$group == 2 & met_hvlt_df_wide$sex == 1 & 
     met_hvlt_df_wide$time_point == 4] <- "conc_m_3wpi"

#Concussion, 4WPI - both sexes and tasks 1-3
met_hvlt_df_wide$gr_sex_tp[met_hvlt_df_wide$group == 2 & met_hvlt_df_wide$sex == 2 & 
    met_hvlt_df_wide$time_point == 5] <- "conc_f_4wpi"
met_hvlt_df_wide$gr_sex_tp[met_hvlt_df_wide$group == 2 & met_hvlt_df_wide$sex == 1 & 
    met_hvlt_df_wide$time_point == 5] <- "conc_m_4wpi"

#Concussion, 6WPI - both sexes and tasks 1-3
met_hvlt_df_wide$gr_sex_tp[met_hvlt_df_wide$group == 2 & met_hvlt_df_wide$sex == 2 & 
    met_hvlt_df_wide$time_point == 6] <- "conc_f_6wpi"
met_hvlt_df_wide$gr_sex_tp[met_hvlt_df_wide$group == 2 & met_hvlt_df_wide$sex == 1 & 
    met_hvlt_df_wide$time_point == 6] <- "conc_m_6wpi"

#Concussion, 8WPI - both sexes and tasks 1-3
met_hvlt_df_wide$gr_sex_tp[met_hvlt_df_wide$group == 2 & met_hvlt_df_wide$sex == 2 & 
     met_hvlt_df_wide$time_point == 7] <- "conc_f_8wpi"
met_hvlt_df_wide$gr_sex_tp[met_hvlt_df_wide$group == 2 & met_hvlt_df_wide$sex == 1 & 
     met_hvlt_df_wide$time_point == 7] <- "conc_m_8wpi"

met_hvlt_df_wide$gr_sex_tp_int <- factor(met_hvlt_df_wide$gr_sex_tp,
      levels = c("ctl_f_bl","ctl_m_bl","conc_f_1wpi","conc_m_1wpi","conc_f_2wpi",
      "conc_m_2wpi","conc_f_3wpi","conc_m_3wpi","conc_f_4wpi","conc_m_4wpi",
       "conc_f_6wpi","conc_m_6wpi","conc_f_8wpi","conc_m_8wpi"))
met_hvlt_df_wide$gr_sex_tp_int <- as.integer(met_hvlt_df_wide$gr_sex_tp_int)
