  ####Delayed HVLT Functions####
met_delhvlt_func <- function(samples) {
  samples <- samples[c(1:11,181:194,179:180)]
  colnames(samples) <- c("ctl","conc","male","female","bl","onewpi","twowpi",
                         "threewpi","fourwpi","sixwpi","eightwpi","ctl_f_bl.int",
                         "ctl_m_bl.int","conc_f_1wpi.int","conc_m_1wpi.int","conc_f_2wpi.int",
                         "conc_m_2wpi.int","conc_f_3wpi.int","conc_m_3wpi.int","conc_f_4wpi.int",
                         "conc_m_4wpi.int","conc_f_6wpi.int","conc_m_6wpi.int","conc_f_8wpi.int",
                         "conc_m_8wpi.int","mu_id","sig_id")
  samples$ctl_f_bl <- samples$ctl+samples$female+samples$bl+samples$ctl_f_bl.int
  samples$ctl_m_bl <- samples$ctl+samples$male+samples$bl+samples$ctl_m_bl.int
  
  samples$conc_f_1wpi <- samples$conc+samples$female+samples$onewpi+samples$conc_f_1wpi.int
  samples$conc_m_1wpi <- samples$conc+samples$male+samples$onewpi+samples$conc_m_1wpi.int
  
  samples$conc_f_2wpi <- samples$conc+samples$female+samples$twowpi+samples$conc_f_2wpi.int
  samples$conc_m_2wpi <- samples$conc+samples$male+samples$twowpi+samples$conc_m_2wpi.int
  
  samples$conc_f_3wpi <- samples$conc+samples$female+samples$threewpi+samples$conc_f_3wpi.int
  samples$conc_m_3wpi <- samples$conc+samples$male+samples$threewpi+samples$conc_m_3wpi.int
  
  samples$conc_f_4wpi <- samples$conc+samples$female+samples$fourwpi+samples$conc_f_4wpi.int
  samples$conc_m_4wpi <- samples$conc+samples$male+samples$fourwpi+samples$conc_m_4wpi.int
  
  samples$conc_f_6wpi <- samples$conc+samples$female+samples$sixwpi+samples$conc_f_6wpi.int
  samples$conc_m_6wpi <- samples$conc+samples$male+samples$sixwpi+samples$conc_m_6wpi.int
  
  samples$conc_f_8wpi <- samples$conc+samples$female+samples$eightwpi+samples$conc_f_8wpi.int
  samples$conc_m_8wpi <- samples$conc+samples$male+samples$eightwpi+samples$conc_m_8wpi.int
  
  samples[c(42:66)] <- apply(samples[c(1:11,28:41)],2,function(x) (exp(x)/(1+exp(x))*12))
  colnames(samples) <- c(paste(colnames(samples[c(1:25)]),"log",sep="_"),colnames(samples[c(26:27)]),
                         paste(colnames(samples[c(28:41)]),"log",sep="_"),colnames(samples[c(1:11,28:41)]))
  assign("samples",samples,envir = .GlobalEnv)
}

ppc_met_delhvlt_binom_func <- function(samples,num_max) {
  extracted_samples <- samples[c(1:11,181:194,179,180)]
  colnames(extracted_samples) <- c("ctl","conc","male","female","bl","onewpi","twowpi",
                                   "threewpi","fourwpi","sixwpi","eightwpi","ctl_f_bl.int",
                                   "ctl_m_bl.int","conc_f_1wpi.int","conc_m_1wpi.int","conc_f_2wpi.int",
                                   "conc_m_2wpi.int","conc_f_3wpi.int","conc_m_3wpi.int","conc_f_4wpi.int",
                                   "conc_m_4wpi.int","conc_f_6wpi.int","conc_m_6wpi.int","conc_f_8wpi.int",
                                   "conc_m_8wpi.int","mu_id","sig_id")
  
  #Creating the b_id parameter
  extracted_samples$b_id <- NA
  for (i in 1:length(extracted_samples$b_id)) {
    extracted_samples$b_id[i] <- rnorm(1,mean=extracted_samples$mu_id[i],sd=extracted_samples$sig_id[i])
  }
  
  pred_df <- as.data.frame(matrix(NA,nrow=1000,ncol=14))
  colnames(pred_df) <- c("ctl_f_bl","ctl_m_bl","conc_f_1wpi","conc_m_1wpi","conc_f_2wpi",
                         "conc_m_2wpi","conc_f_3wpi","conc_m_3wpi","conc_f_4wpi",
                         "conc_m_4wpi","conc_f_6wpi","conc_m_6wpi","conc_f_8wpi","conc_m_8wpi")
  
  sample_num <- sample(1:4000,1000,replace=FALSE)
  for (i in 1:length(sample_num)) {
    extracted_row <- extracted_samples[sample_num[i],]
    
    pred_df$ctl_f_bl[i] <- rbinom(1,size=num_max,prob=(exp(extracted_row$ctl+extracted_row$female+extracted_row$bl+extracted_row$ctl_f_bl.int)/
           (1+exp(extracted_row$ctl+extracted_row$female+extracted_row$bl+extracted_row$ctl_f_bl.int))))
    pred_df$ctl_m_bl[i] <- rbinom(1,size=num_max,prob=(exp(extracted_row$ctl+extracted_row$male+extracted_row$bl+extracted_row$ctl_m_bl.int)/
           (1+exp(extracted_row$ctl+extracted_row$male+extracted_row$bl+extracted_row$ctl_m_bl.int))))
    
    pred_df$conc_f_1wpi[i] <- rbinom(1,size=num_max,prob=(exp(extracted_row$conc+extracted_row$female+extracted_row$onewpi+extracted_row$conc_f_1wpi.int+extracted_row$b_id)/
           (1+exp(extracted_row$conc+extracted_row$female+extracted_row$onewpi+extracted_row$conc_f_1wpi.int+extracted_row$b_id))))
    pred_df$conc_m_1wpi[i] <- rbinom(1,size=num_max,prob=(exp(extracted_row$conc+extracted_row$male+extracted_row$onewpi+extracted_row$conc_m_1wpi.int+extracted_row$b_id)/
          (1+exp(extracted_row$conc+extracted_row$male+extracted_row$onewpi+extracted_row$conc_m_1wpi.int+extracted_row$b_id))))
    
    pred_df$conc_f_2wpi[i] <- rbinom(1,size=num_max,prob=(exp(extracted_row$conc+extracted_row$female+extracted_row$twowpi+extracted_row$conc_f_2wpi.int+extracted_row$b_id)/
           (1+exp(extracted_row$conc+extracted_row$female+extracted_row$twowpi+extracted_row$conc_f_2wpi.int+extracted_row$b_id))))
    pred_df$conc_m_2wpi[i] <- rbinom(1,size=num_max,prob=(exp(extracted_row$conc+extracted_row$male+extracted_row$twowpi+extracted_row$conc_m_2wpi.int+extracted_row$b_id)/
           (1+exp(extracted_row$conc+extracted_row$male+extracted_row$twowpi+extracted_row$conc_m_2wpi.int+extracted_row$b_id))))
    
    pred_df$conc_f_3wpi[i] <- rbinom(1,size=num_max,prob=(exp(extracted_row$conc+extracted_row$female+extracted_row$threewpi+extracted_row$conc_f_3wpi.int+extracted_row$b_id)/
           (1+exp(extracted_row$conc+extracted_row$female+extracted_row$threewpi+extracted_row$conc_f_3wpi.int+extracted_row$b_id))))
    pred_df$conc_m_3wpi[i] <- rbinom(1,size=num_max,prob=(exp(extracted_row$conc+extracted_row$male+extracted_row$threewpi+extracted_row$conc_m_3wpi.int+extracted_row$b_id)/
           (1+exp(extracted_row$conc+extracted_row$male+extracted_row$threewpi+extracted_row$conc_m_3wpi.int+extracted_row$b_id))))
    
    pred_df$conc_f_4wpi[i] <- rbinom(1,size=num_max,prob=(exp(extracted_row$conc+extracted_row$female+extracted_row$fourwpi+extracted_row$conc_f_4wpi.int+extracted_row$b_id)/
           (1+exp(extracted_row$conc+extracted_row$female+extracted_row$fourwpi+extracted_row$conc_f_4wpi.int+extracted_row$b_id))))
    pred_df$conc_m_4wpi[i] <- rbinom(1,size=num_max,prob=(exp(extracted_row$conc+extracted_row$male+extracted_row$fourwpi+extracted_row$conc_m_4wpi.int+extracted_row$b_id)/
           (1+exp(extracted_row$conc+extracted_row$male+extracted_row$fourwpi+extracted_row$conc_m_4wpi.int+extracted_row$b_id))))
    
    pred_df$conc_f_6wpi[i] <- rbinom(1,size=num_max,prob=(exp(extracted_row$conc+extracted_row$female+extracted_row$sixwpi+extracted_row$conc_f_6wpi.int+extracted_row$b_id)/
          (1+exp(extracted_row$conc+extracted_row$female+extracted_row$sixwpi+extracted_row$conc_f_6wpi.int+extracted_row$b_id))))
    pred_df$conc_m_6wpi[i] <- rbinom(1,size=num_max,prob=(exp(extracted_row$conc+extracted_row$male+extracted_row$sixwpi+extracted_row$conc_m_6wpi.int+extracted_row$b_id)/
           (1+exp(extracted_row$conc+extracted_row$male+extracted_row$sixwpi+extracted_row$conc_m_6wpi.int+extracted_row$b_id))))
    
    pred_df$conc_f_8wpi[i] <- rbinom(1,size=num_max,prob=(exp(extracted_row$conc+extracted_row$female+extracted_row$eightwpi+extracted_row$conc_f_8wpi.int+extracted_row$b_id)/
           (1+exp(extracted_row$conc+extracted_row$female+extracted_row$eightwpi+extracted_row$conc_f_8wpi.int+extracted_row$b_id))))
    pred_df$conc_m_8wpi[i] <- rbinom(1,size=num_max,prob=(exp(extracted_row$conc+extracted_row$male+extracted_row$eightwpi+extracted_row$conc_m_8wpi.int+extracted_row$b_id)/
           (1+exp(extracted_row$conc+extracted_row$male+extracted_row$eightwpi+extracted_row$conc_m_8wpi.int+extracted_row$b_id))))
  }
  assign("pred_df",pred_df,envir = .GlobalEnv)
}

