  ####Real MET HVLT####
dat_met_delhvlt <- list(N = length(met_delhvlt_df_wide$new_id),
     N_ids = length(unique(met_delhvlt_df_wide$new_id)),
     group = as.integer(met_delhvlt_df_wide$group),
     sex = as.integer(met_delhvlt_df_wide$sex),
     timepoint = as.integer(met_delhvlt_df_wide$time_point),
     gr_sex_tp = met_delhvlt_df_wide$gr_sex_tp_int,
     id = as.integer(met_delhvlt_df_wide$new_id),
     outcome = (met_delhvlt_df_wide$delhvlt),
     M = 12)
str(dat_met_delhvlt)

#Running model now
met_delhvlt_model <- sampling(met_delhvlt_mod, dat = dat_met_delhvlt)
precis(met_delhvlt_model,depth=2)
saveRDS(met_delhvlt_model, "met_delhvlt_model.rds")
met_delhvlt_model <- readRDS("met_delhvlt_model.rds")

#Looking at LOO
loo_delhvlt_mod <- loo(met_delhvlt_model)
plot(loo_delhvlt_mod,diagnostic = c("k"),label_points = FALSE,main = "PSIS diagnostic plot")
print(which(loo_delhvlt_mod$diagnostics$pareto_k > 0.7))

post <- (rstan::extract(met_delhvlt_model))
high_k <- which(loo_delhvlt_mod$diagnostics$pareto_k > 0.7)
pi <- colMeans(post$pi)  # Mean posterior pi
expected_counts <- 12 * pi
plot(met_delhvlt_df_wide$delhvlt[high_k], expected_counts[high_k], 
     xlab = "Observed Count", ylab = "Expected Count", 
     main = "High Pareto-k Observations")
abline(0, 1, col = "red")
rm(post,high_k,pi,expected_counts)

#check chains
traceplot(met_delhvlt_model, pars = c('b_group'))
traceplot(met_delhvlt_model, pars = c('b_sex'))
traceplot(met_delhvlt_model, pars = c('b_time_point'))

#Extracting samples
met_delhvlt_samples <- as.data.frame(rstan::extract(met_delhvlt_model))
colnames(met_delhvlt_samples)

met_delhvlt_func(met_delhvlt_samples)
met_delhvlt_samples <- samples
colnames(met_delhvlt_samples)
apply(met_delhvlt_samples[c(42:66)],2,summary)
rm(samples)

