                             "Step Down + Choice Lateral Jump (number of correct trials /12)",
                             "Jump-Overs (number in 20 seconds)",
                             "Jump-Overs + Delayed HVLT (number in 20 seconds)","Delayed HVLT (number of words [/12])")
post_perf_data$Group <- c(rep(" Healthy",8000),rep("Concussion Week 1",8000),
                        rep("Concussion Week 2",8000),rep("Concussion Week 3",8000),rep("Concussion Week 4",8000),
                        rep("Concussion Week 6",8000),rep("Concussion Week 8",8000))
post_perf_data$Sex <- rep(c(rep("Female",4000),rep("Male",4000)),7)
post_perf_data <- post_perf_data[-c(1)]

met_perf_post_table <- 
  tbl_strata(post_perf_data, 
             strata = 'Group',
             .tbl_fun =
               ~ .x %>%
               tbl_summary(by = `Sex`, missing = "no",
                           digits=list("Total HVLT (number of words [/36])" ~ 0,
                                       '10 Squats (completion time [seconds])' ~ 1,
                                       '10 Lunges (completion time [seconds])' ~ 1,
                                       '10 Hip Hinges (completion time [seconds])' ~ 1,
                                       "20 Squats + COWAT (number of words)" ~ 0,
                                       "20 Lunges + COWAT (number of words)" ~ 0, 
                                       "20 Hip Hinges + COWAT (number of words)" ~ 0,
                                       "Step Down + Choice Lateral Jump (number of correct trials /12)" ~ 0,
                                       "Jump-Overs (number in 20 seconds)" ~ 0,
                                       "Jump-Overs + Delayed HVLT (number in 20 seconds)" ~ 0,
                                       "Delayed HVLT (number of words [/12])" ~ 0),
                           type = list("Total HVLT (number of words [/36])" ~ 'continuous',
                                       '10 Squats (completion time [seconds])' ~ 'continuous',
                                       '10 Lunges (completion time [seconds])' ~ 'continuous',
                                       '10 Hip Hinges (completion time [seconds])' ~ 'continuous',
                                       "20 Squats + COWAT (number of words)" ~ 'continuous',
                                       "20 Lunges + COWAT (number of words)" ~ 'continuous', 
                                       "20 Hip Hinges + COWAT (number of words)" ~ 'continuous',
                                       "Step Down + Choice Lateral Jump (number of correct trials /12)" ~ 'continuous',
                                       "Jump-Overs (number in 20 seconds)" ~ 'continuous',
                                       "Jump-Overs + Delayed HVLT (number in 20 seconds)" ~ 'continuous',
                                       "Delayed HVLT (number of words [/12])" ~ 'continuous'),
                             statistic = list(all_continuous() ~ c("{mean} ({HDILow}, {HDIHigh})")))) %>%
  modify_caption("**MET - Performance Metrics Posteriors**")%>%
  as_gt() %>%
  tab_row_group(label = "Pre-MET", id = "Pre-MET",rows = 1:1) %>% 
  tab_row_group(label = "MET - Stage 2", id = "MET - Stage 2",rows = 2:4) %>% 
  tab_row_group(label = "MET - Stage 3", id = "MET - Stage 3",rows = 5:7) %>% 
  tab_row_group(label = "MET - Stage 4", id = "MET - Stage 4",rows = 8:11) %>%
  row_group_order(groups = c("Pre-MET","MET - Stage 2","MET - Stage 3","MET - Stage 4"))%>%
  tab_style( style = cell_text(weight = "bold"),
             locations = cells_row_groups(groups= c("Pre-MET","MET - Stage 2",
                        "MET - Stage 3","MET - Stage 4"))) %>%
  fmt(columns = everything(),
      fns = function(x) ifelse(x == "", "0 (0)", x))%>%
  tab_source_note(md(""))  %>%
  gt::tab_options(table.font.names = "Times New Roman")%>%
  gt::gtsave(filename = "met_perf_post.html")

