post_perf_conc_ctl_diff_data <- cbind.data.frame(gather(met_hvlt_samples[c(67:78)]),
                                   gather(met2_tasks_samples[c(161:172)]),
                                   gather(met2_tasks_samples[c(173:184)]),
                                   gather(met2_tasks_samples[c(185:196)]),
